const state={view:'dashboard',currentProjectId:null,currentEmployeeId:null,projectTab:'summary',selectedProjectId:null,period:defaultPeriod(),projects:[],categories:[],employees:[],bitrixUser:null,projectCache:new Map(),filters:{q:'',status:'',manager:'',client:'',health:'',minRent:'',movement:'',sort:'profit',view:'table'},op:{q:'',type:'',project:'',category:'',party:'',min:''},doc:{q:'',project:'',type:'',source:'',sync:'',min:''},emp:{q:'',role:'',sort:'profit'}};
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const fmt=new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',minimumFractionDigits:2,maximumFractionDigits:2});
const nf=new Intl.NumberFormat('ru-RU');
function localISO(d=new Date()){const z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}`}
function defaultPeriod(){const d=new Date(),start=new Date(d.getFullYear(),d.getMonth(),1);return{start:localISO(start),end:localISO(d),mode:'month'}}
function dateRu(s){if(!s)return '—';const[y,m,d]=s.split('-');return `${d}.${m}.${y}`}
function monthRu(s){const [y,m]=s.split('-');return new Date(+y,+m-1,1).toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function initials(v=''){return String(v).trim().split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'?'}
function qsPeriod(extra={}){const q=new URLSearchParams({date_from:state.period.start,date_to:state.period.end,...extra});return q.toString()}
async function api(url,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(state.bitrixUser)headers['X-Bitrix-User']=`${state.bitrixUser.ID}: ${state.bitrixUser.NAME||''} ${state.bitrixUser.LAST_NAME||''}`.trim();const res=await fetch(url,{...options,headers});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);return data}
function toast(msg){const e=$('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),2100)}
function showError(e){console.error(e);toast(e.message||'Ошибка');}
function statusText(s){return s==='active'?'В работе':s==='paused'?'На паузе':s==='done'?'Завершён':'—'}
function healthText(s){return s==='excellent'?'Отлично':s==='risk'?'Риск':'Стабильно'}
function healthMicro(s){return s==='excellent'?'Сильная экономика':s==='risk'?'Есть критический финансовый показатель':'Показатели в допустимом диапазоне'}
function pluralRu(n,one,two,five){n=Math.abs(n)%100;const last=n%10;if(n>10&&n<20)return five;if(last>1&&last<5)return two;if(last===1)return one;return five}
function statusPill(p){return `<span class="pill ${p.status}">${statusText(p.status)}</span>`}
function healthPill(p){return `<span class="pill ${p.financial_health}">${healthText(p.financial_health)}</span>`}
function kpi(label,value,sub='',cls='',attrs=''){const inner=`<div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div>${attrs?'<div class="drill">Развернуть →</div>':''}`;return attrs?`<button type="button" class="kpi ${cls} clickable" ${attrs}>${inner}</button>`:`<div class="kpi ${cls}">${inner}</div>`}
function progress(v,max){return Math.max(0,Math.min(100,max?Number(v)/Number(max)*100:0))}
function totalRent(t){return t.completed?t.profit/t.completed*100:0}
function projectTotal(list){return list.reduce((a,p)=>{a.deal+=p.deal_amount_period||0;a.completed+=p.completed||0;a.received+=p.received||0;a.expenses+=p.expenses||0;a.profit+=p.profit||0;a.receivable+=p.receivable||0;return a},{deal:0,completed:0,received:0,expenses:0,profit:0,receivable:0})}
function updateTop(){ $('#globalPeriod').textContent=`${dateRu(state.period.start)} — ${dateRu(state.period.end)}`;$$('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view||(state.view==='project'&&b.dataset.view==='dashboard')||(state.view==='employeeDetail'&&b.dataset.view==='employees')))}
async function loadBase(){const [projects,categories,employees]=await Promise.all([api(`/api/projects?${qsPeriod()}`),api('/api/categories'),api('/api/employees')]);state.projects=projects;state.categories=categories;state.employees=employees}
async function refresh(){state.projectCache.clear();await loadBase();return render()}
function setContent(html){const c=$('#content');c.onclick=null;c.innerHTML=html}
function setPeriod(mode){const now=new Date(),e=new Date(now),s=new Date(now);if(mode==='month')s.setDate(1);if(mode==='30')s.setTime(now.getTime()-29*86400000);if(mode==='prev'){s.setFullYear(now.getFullYear(),now.getMonth()-1,1);e.setFullYear(now.getFullYear(),now.getMonth(),0)}state.period={start:localISO(s),end:localISO(e),mode};state.selectedProjectId=null;refresh().catch(showError)}
function periodControls(id='globalFilters'){return `<div class="filters" id="${id}"><div class="filter"><label>Период с</label><input class="input date-input" type="date" data-period-start value="${state.period.start}"></div><div class="filter"><label>По</label><input class="input date-input" type="date" data-period-end value="${state.period.end}"></div><div class="filter"><label>Быстрый период</label><div class="quick-periods"><button data-period="month" class="${state.period.mode==='month'?'active':''}">Текущий месяц</button><button data-period="30" class="${state.period.mode==='30'?'active':''}">30 дней</button><button data-period="prev" class="${state.period.mode==='prev'?'active':''}">Прошлый месяц</button></div></div></div>`}
function bindPeriod(root=document,rerender=refresh){$$('[data-period]',root).forEach(b=>b.onclick=()=>setPeriod(b.dataset.period));const s=$('[data-period-start]',root),e=$('[data-period-end]',root);const apply=()=>{if(!s||!e||!s.value||!e.value||s.value>e.value)return;state.period={start:s.value,end:e.value,mode:'custom'};state.selectedProjectId=null;rerender().catch(showError)};s?.addEventListener('change',apply);e?.addEventListener('change',apply)}
function hasProjectMovement(p){return Math.abs(p.completed||0)>0||Math.abs(p.received||0)>0||Math.abs(p.expenses||0)>0}
function filteredProjects(){const f=state.filters,q=f.q.toLowerCase();let list=state.projects.filter(p=>(!q||`${p.name} ${p.client} ${p.manager?.name||''}`.toLowerCase().includes(q))&&(!f.status||p.status===f.status)&&(!f.manager||String(p.manager_employee_id||'')===f.manager)&&(!f.client||String(p.client||'')===f.client)&&(!f.health||p.financial_health===f.health)&&(f.minRent===''||p.profitability>=+f.minRent)&&(!f.movement||(f.movement==='yes'?hasProjectMovement(p):!hasProjectMovement(p))));list.sort((a,b)=>f.sort==='rent'?b.profitability-a.profitability:f.sort==='deal'?b.deal_amount-a.deal_amount:f.sort==='name'?a.name.localeCompare(b.name,'ru'):b.profit-a.profit);return list}
function dashboardFilters(){const f=state.filters,clients=[...new Set(state.projects.map(p=>p.client).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ru'));return `<div class="filters dashboard-filters"><div class="dashboard-filter-row primary"><div class="filter"><label>Период с</label><input class="input date-input" type="date" data-period-start value="${state.period.start}"></div><div class="filter"><label>По</label><input class="input date-input" type="date" data-period-end value="${state.period.end}"></div><div class="filter quick-filter"><label>Быстрый период</label><div class="quick-periods"><button data-period="month" class="${state.period.mode==='month'?'active':''}">Текущий месяц</button><button data-period="30" class="${state.period.mode==='30'?'active':''}">30 дней</button><button data-period="prev" class="${state.period.mode==='prev'?'active':''}">Прошлый месяц</button></div></div><div class="filter search-filter"><label>Поиск</label><input class="search" id="fQ" value="${esc(f.q)}" placeholder="Проект, клиент, менеджер"></div><div class="filter"><label>Статус</label><select class="select" id="fStatus"><option value="">Все</option>${['active','paused','done'].map(v=>`<option value="${v}" ${f.status===v?'selected':''}>${statusText(v)}</option>`).join('')}</select></div><div class="filter manager-filter"><label>Менеджер</label><select class="select" id="fManager"><option value="">Все</option>${state.employees.map(e=>`<option value="${e.id}" ${f.manager==e.id?'selected':''}>${esc(e.name)}${e.role?` · ${esc(e.role)}`:''}</option>`).join('')}</select></div><div class="filter"><label>Клиент</label><select class="select" id="fClient"><option value="">Все</option>${clients.map(c=>`<option value="${esc(c)}" ${f.client===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="filter"><label>Состояние</label><select class="select" id="fHealth"><option value="">Все</option><option value="excellent" ${f.health==='excellent'?'selected':''}>Отлично</option><option value="stable" ${f.health==='stable'?'selected':''}>Стабильно</option><option value="risk" ${f.health==='risk'?'selected':''}>Риск</option></select></div></div><div class="dashboard-filter-row secondary"><div class="filter"><label>Мин. рент., %</label><input class="input" id="fRent" type="number" value="${f.minRent}" placeholder="%"></div><div class="filter"><label>Движение</label><select class="select" id="fMovement"><option value="" ${!f.movement?'selected':''}>Все</option><option value="yes" ${f.movement==='yes'?'selected':''}>Есть движение</option><option value="no" ${f.movement==='no'?'selected':''}>Без движения</option></select></div><div class="filter"><label>Сортировка</label><select class="select" id="fSort"><option value="profit" ${f.sort==='profit'?'selected':''}>Прибыль ↓</option><option value="rent" ${f.sort==='rent'?'selected':''}>Рентабельность ↓</option><option value="deal" ${f.sort==='deal'?'selected':''}>Сумма сделки ↓</option><option value="name" ${f.sort==='name'?'selected':''}>Название</option></select></div><button class="btn small dashboard-reset" type="button" data-reset-dashboard>Сбросить</button></div></div>`}
function pipelineKpis(list,single=false){const t=projectTotal(list),p=single?list[0]:null,a=m=>p?`data-metric="${m}" data-project-id="${p.id}"`:`data-portfolio-metric="${m}"`;return `<div class="pipeline-kpis">${kpi(single?'Сумма сделки':'Сумма сделок за период',fmt.format(single?(p?.deal_amount||0):t.deal),single?'Полная договорная стоимость':`По дате сделки · ${dateRu(state.period.start)} — ${dateRu(state.period.end)}`,'',single?'':a('deal'))}${kpi('Выполнено',fmt.format(t.completed),'Закрытые работы в периоде','blue',a('completed'))}${kpi('Получено',fmt.format(t.received),'Фактически поступившие деньги','received',a('received'))}${kpi('Расходы',fmt.format(t.expenses),'Расходы периода','expense',a('expenses'))}${kpi('Прибыль',fmt.format(t.profit),'Выполнено − Расходы',t.profit<0?'expense':'',a('profit'))}${kpi('Рентабельность',totalRent(t).toFixed(1)+'%','Прибыль / Выполнено × 100%','',single?'':a('profitability'))}${kpi(single?'Общая дебиторка проекта':'Общая дебиторка',fmt.format(t.receivable),'Накопительно на конец периода',t.receivable?'warn':'',p?`data-debt="${p.id}"`:a('receivable'))}</div>`}
async function dashboardMonthlySeries(projectIds){const ids=new Set(projectIds),windows=rollingMonthWindows(state.period.end,5);return Promise.all(windows.map(async w=>{const data=await api(`/api/dashboard?date_from=${w.start}&date_to=${w.end}`),ps=data.projects.filter(p=>ids.has(p.id)),t=projectTotal(ps);return{...w,completed:t.completed,received:t.received,expenses:t.expenses}}))}
function dashboardDynamics(series,count){return `<div class="panel dashboard-dynamics"><div class="panel-head"><div><h2>Финансовая динамика портфеля</h2><p>${count} ${pluralRu(count,'проект','проекта','проектов')} в выборке</p></div><div class="chart-legend"><span class="blue">● Выполнено</span><span class="good">● Получено</span><span class="bad">● Расходы</span></div></div><div class="panel-body">${chartBars(series,[{key:'completed',label:'Выполнено',cls:'blue'},{key:'received',label:'Получено',cls:'good'},{key:'expenses',label:'Расходы',cls:'bad'}])}<div class="dashboard-chart-hint">Кликните на месяц для точных значений.</div></div></div>`}
function dashboardHealth(list){return `<div class="panel dashboard-health"><div class="panel-head"><div><h2>Финансовое состояние</h2><p>Кликните: факт → порог → причина оценки</p></div></div><div class="panel-body dashboard-health-list">${['excellent','stable','risk'].map(h=>{const n=list.filter(p=>p.financial_health===h).length;return `<button class="dashboard-health-row" data-health-drill="${h}"><div><b class="${h==='excellent'?'good':h==='risk'?'bad':'blue'}">${healthText(h)}</b><small>${healthMicro(h)}</small></div><strong class="${h==='excellent'?'good':h==='risk'?'bad':'blue'}">${n}</strong><div class="track"><i class="fill ${h==='excellent'?'good':h==='risk'?'bad':'blue'}" style="width:${progress(n,Math.max(1,list.length))}%"></i></div></button>`}).join('')}</div></div>`}
function dashboardMetricBar(value,max,cls=''){return `<div class="dashboard-table-metric"><b class="${cls}">${value}</b><div class="track"><i class="fill ${cls==='warn'?'warn':cls==='bad'?'bad':cls==='blue'?'blue':'good'}" style="width:${progress(Math.abs(parseFloat(String(value).replace(/[^0-9.-]/g,''))||0),Math.max(1,max))}%"></i></div></div>`}
function dashboardTable(list){const t=projectTotal(list),fullDealTotal=list.reduce((sum,p)=>sum+(p.deal_amount||0),0),maxProfit=Math.max(1,...list.map(p=>Math.abs(p.profit||0)));return `<div class="panel dashboard-projects"><div class="panel-head"><div><h2>Проекты</h2><p>${list.length} ${pluralRu(list.length,'проект','проекта','проектов')} в текущей выборке · 1 клик — фокус · 2 клика — drill-down</p></div></div><div class="table-wrap"><table><thead><tr><th>Проект</th><th>Статус</th><th>Состояние</th><th>Менеджер</th><th>Сумма сделки</th><th>Выполнено</th><th>Получено</th><th>Расходы</th><th>Прибыль</th><th>Рентабельность</th><th>Общая дебиторка проекта</th></tr></thead><tbody>${list.length?list.map(p=>{const completionPct=progress(p.completed_cumulative||0,p.deal_amount||0);return `<tr class="click-row" data-open-project="${p.id}"><td><b>${esc(p.name)}</b><div class="muted" style="font-size:8px">${esc(p.client||'Без клиента')}</div></td><td>${statusPill(p)}</td><td>${healthPill(p)}</td><td>${esc(p.manager?.name||'Не назначен')}</td><td><div class="dashboard-table-metric" title="Выполнено накопительно: ${completionPct.toFixed(1)}%"><b>${fmt.format(p.deal_amount||0)}</b><div class="track"><i class="fill blue" style="width:${completionPct}%"></i></div></div></td><td class="blue">${fmt.format(p.completed)}</td><td class="good">${fmt.format(p.received)}</td><td class="bad">${fmt.format(p.expenses)}</td><td><div class="dashboard-table-metric"><b class="${p.profit<0?'bad':'good'}">${fmt.format(p.profit)}</b><div class="track"><i class="fill ${p.profit<0?'bad':'good'}" style="width:${progress(Math.abs(p.profit),maxProfit)}%"></i></div></div></td><td><div class="dashboard-table-metric"><b>${p.profitability.toFixed(1)}%</b><div class="track"><i class="fill good" style="width:${Math.min(100,Math.max(0,p.profitability))}%"></i></div></div></td><td class="warn" data-debt="${p.id}">${fmt.format(p.receivable)}</td></tr>`}).join(''):`<tr><td colspan="11" class="empty-cell">Нет проектов, соответствующих фильтрам.</td></tr>`}</tbody><tfoot><tr><td colspan="4">Итого · ${list.length}</td><td>${fmt.format(fullDealTotal)}</td><td class="blue">${fmt.format(t.completed)}</td><td class="good">${fmt.format(t.received)}</td><td class="bad">${fmt.format(t.expenses)}</td><td>${fmt.format(t.profit)}</td><td>${totalRent(t).toFixed(1)}%</td><td class="warn">${fmt.format(t.receivable)}</td></tr></tfoot></table></div></div>`}
function dashboardProjectCards(list){return `<div class="panel dashboard-projects"><div class="panel-head"><div><h2>Проекты</h2><p>${list.length} ${pluralRu(list.length,'проект','проекта','проектов')} · карточный вид</p></div></div><div class="cards-view">${list.map(p=>`<article class="project-card ${p.financial_health==='excellent'?'goodcard':p.financial_health==='risk'?'riskcard':'stablecard'}" data-open-project="${p.id}"><i class="card-accent ${p.financial_health==='excellent'?'good':p.financial_health==='risk'?'bad':'blue'}"></i><div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start"><div><h3>${esc(p.name)}</h3><p>${esc(p.client||'Без клиента')} · ${esc(p.manager?.name||'Не назначен')}</p></div>${healthPill(p)}</div><div class="card-bars"><div class="card-bar-row"><span>Выполнено</span><div class="track"><i class="fill blue" style="width:${progress(p.completed,Math.max(1,p.deal_amount||p.completed))}%"></i></div><b class="blue">${fmt.format(p.completed)}</b></div><div class="card-bar-row"><span>Получено</span><div class="track"><i class="fill good" style="width:${progress(p.received,Math.max(1,p.completed||p.received))}%"></i></div><b class="good">${fmt.format(p.received)}</b></div><div class="card-bar-row"><span>Расходы</span><div class="track"><i class="fill bad" style="width:${progress(p.expenses,Math.max(1,p.completed||p.expenses))}%"></i></div><b class="bad">${fmt.format(p.expenses)}</b></div></div><div class="project-card-footer"><div><small>Прибыль</small><b class="${p.profit<0?'bad':'good'}">${fmt.format(p.profit)}</b></div><div><small>Рентабельность</small><b>${p.profitability.toFixed(1)}%</b></div><div data-debt="${p.id}"><small>Дебиторка</small><b class="warn">${fmt.format(p.receivable)}</b></div></div></article>`).join('')||'<div class="metric-empty">Нет проектов, соответствующих фильтрам.</div>'}</div></div>`}
function dashboardViewToggle(){return `<div class="dashboard-view-toggle" role="group" aria-label="Вид проектов"><button class="${state.filters.view==='table'?'active':''}" data-dashboard-view="table">Таблица</button><button class="${state.filters.view==='cards'?'active':''}" data-dashboard-view="cards">Карточки</button></div>`}
async function renderDashboard(){const data=await api(`/api/dashboard?${qsPeriod()}`);state.projects=data.projects;const list=filteredProjects(),series=await dashboardMonthlySeries(list.map(p=>p.id));$('#crumbCurrent').textContent='/ Обзор';setContent(`<div class="page-head overview-head"><div><h1>Экономика проектов</h1><p>Сделка → Выполнено → Получено → Расходы → Прибыль → Рентабельность → Дебиторка</p></div><div class="head-actions overview-actions">${dashboardViewToggle()}<button class="btn" data-add-completion>+ Выполнение</button><button class="btn" data-add-op>+ Операция</button><button class="btn primary" data-add-project>+ Новый проект</button></div></div><div class="action-steps"><button class="action-step" data-add-project><b>1. Создайте проект</b><small>Задайте клиента, менеджера и сумму сделки</small></button><button class="action-step" data-add-completion><b>2. Фиксируйте выполнение</b><small>Закрывайте этапы выполненных работ</small></button><button class="action-step" data-add-op><b>3. Вносите деньги и расходы</b><small>Поступления и затраты не смешиваются с выполнением</small></button></div>${dashboardFilters()}${pipelineKpis(list)}<div class="grid2 overview-insights">${dashboardDynamics(series,list.length)}${dashboardHealth(list)}</div><div style="margin-top:12px">${state.filters.view==='cards'?dashboardProjectCards(list):dashboardTable(list)}</div>`);bindDashboard();bindCommon()}
function bindDashboard(){bindPeriod(document,refresh);const map={fQ:'q',fStatus:'status',fManager:'manager',fClient:'client',fHealth:'health',fRent:'minRent',fMovement:'movement',fSort:'sort'};for(const[id,k]of Object.entries(map)){const e=$('#'+id);if(id==='fQ')bindLiveFilter(e,v=>state.filters[k]=v,renderDashboard);else if(id==='fRent')bindNumericFilter(e,v=>state.filters[k]=v,renderDashboard);else e?.addEventListener('change',()=>{state.filters[k]=e.value;renderDashboard().catch(showError)})}$$('[data-dashboard-view]').forEach(x=>x.onclick=()=>{state.filters.view=x.dataset.dashboardView;renderDashboard().catch(showError)});$('[data-reset-dashboard]')?.addEventListener('click',()=>{state.filters={...state.filters,q:'',status:'',manager:'',client:'',health:'',minRent:'',movement:'',sort:'profit'};renderDashboard().catch(showError)});$$('[data-open-project]').forEach(r=>r.onclick=e=>{if(e.target.closest('[data-debt]'))return;openProject(+r.dataset.openProject)});$$('[data-debt]').forEach(e=>e.onclick=ev=>{ev.stopPropagation();openDebt(+e.dataset.debt)});bindMetricLinks($('#content'));const content=$('#content');content.onclick=ev=>{const metric=ev.target.closest('[data-portfolio-metric]');if(metric&&content.contains(metric)){ev.preventDefault();ev.stopPropagation();openPortfolioMetric(metric.dataset.portfolioMetric).catch(showError);return}const health=ev.target.closest('[data-health-drill]');if(health&&content.contains(health)){ev.preventDefault();openHealthDrill(health.dataset.healthDrill)}}}
function operationFilters(){const f=state.op;return `${periodControls('opPeriod')}<div class="filters"><div class="filter"><label>Поиск</label><input class="search" id="opQ" value="${esc(f.q)}" placeholder="Проект, статья, контрагент, комментарий"></div><div class="filter"><label>Тип</label><select id="opType"><option value="">Все</option><option value="income" ${f.type==='income'?'selected':''}>Получено</option><option value="expense" ${f.type==='expense'?'selected':''}>Расход</option></select></div><div class="filter"><label>Проект</label><select id="opProject"><option value="">Все</option>${state.projects.map(p=>`<option value="${p.id}" ${f.project==p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="filter"><label>Статья</label><select id="opCategory"><option value="">Все</option>${state.categories.map(c=>`<option value="${c.id}" ${f.category==c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="filter"><label>Сотрудник / контрагент</label><input id="opParty" value="${esc(f.party)}" placeholder="Поиск"></div><div class="filter"><label>Мин. сумма</label><input id="opMin" type="number" value="${f.min}"></div></div>`}
async function renderOperations(){const rows=await api(`/api/transactions?${qsPeriod()}`),f=state.op,q=f.q.toLowerCase();const ops=rows.filter(o=>(!q||`${o.project_name} ${o.category_name} ${o.comment} ${o.employee_name||''} ${o.counterparty||''}`.toLowerCase().includes(q))&&(!f.type||o.type===f.type)&&(!f.project||String(o.project_id)===f.project)&&(!f.category||String(o.category_id)===f.category)&&(!f.party||`${o.employee_name||''} ${o.counterparty||''}`.toLowerCase().includes(f.party.toLowerCase()))&&(!f.min||o.amount>=+f.min));const exp=ops.filter(o=>o.type==='expense'),tot=exp.reduce((s,o)=>s+o.amount,0),cats={};exp.forEach(o=>cats[o.category_name]=(cats[o.category_name]||0)+o.amount);$('#crumbCurrent').textContent='/ Операции';setContent(`<div class="page-head"><div><h1>Операции</h1><p>Поступления и расходы · ${dateRu(state.period.start)} — ${dateRu(state.period.end)}</p></div><button class="btn primary" data-add-op>+ Операция</button></div>${operationFilters()}<div class="grid2"><div>${operationTable(ops)}</div><div class="panel"><div class="panel-head"><div><h2>Расходы по статьям</h2><p>Текущая выборка</p></div></div><div class="panel-body quick-list">${Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="quick-item"><div style="flex:1"><b>${esc(k)}</b><small>${fmt.format(v)} · ${(v/Math.max(1,tot)*100).toFixed(1)}%</small><div class="track"><i class="fill warn" style="width:${progress(v,Math.max(...Object.values(cats),1))}%"></i></div></div></div>`).join('')||'<div class="muted">Расходов нет</div>'}</div></div></div>`);bindCommon();bindPeriod($('#opPeriod'),refresh);const mp={opQ:'q',opType:'type',opProject:'project',opCategory:'category',opParty:'party',opMin:'min'};for(const[id,k]of Object.entries(mp)){const e=$('#'+id);if(id==='opQ'||id==='opParty')bindLiveFilter(e,v=>state.op[k]=v,renderOperations);else if(id==='opMin')bindNumericFilter(e,v=>state.op[k]=v,renderOperations);else e?.addEventListener('change',()=>{state.op[k]=e.value;renderOperations().catch(showError)})}}
function operationTable(rows){return `<div class="panel"><div class="panel-head"><div><h2>Журнал операций</h2><p>${rows.length} записей</p></div></div><div class="table-wrap"><table><thead><tr><th>Дата</th><th>Проект</th><th>Тип</th><th>Статья</th><th>Сотрудник / контрагент</th><th>Комментарий</th><th>Сумма</th></tr></thead><tbody>${rows.length?rows.map(o=>`<tr><td>${dateRu(o.transaction_date)}</td><td><button class="project-link" data-open-project="${o.project_id}">${esc(o.project_name||'')}</button></td><td><span class="pill ${o.type==='income'?'excellent':'risk'}">${o.type==='income'?'Получено':'Расход'}</span></td><td>${esc(o.category_name)}</td><td>${esc(o.employee_name||o.counterparty||'Клиент')}</td><td>${esc(o.comment||'—')}</td><td class="${o.type==='income'?'good':'bad'}">${o.type==='income'?'+':'−'}${fmt.format(o.amount)}</td></tr>`).join(''):`<tr><td colspan="7" class="empty-cell">Нет операций.</td></tr>`}</tbody></table></div></div>`}
function documentFilters(){const f=state.doc;return `${periodControls('docPeriod')}<div class="filters"><div class="filter"><label>Поиск</label><input id="docQ" class="search" value="${esc(f.q)}"></div><div class="filter"><label>Проект</label><select id="docProject"><option value="">Все</option>${state.projects.map(p=>`<option value="${p.id}" ${f.project==p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="filter"><label>Тип</label><input id="docType" value="${esc(f.type)}" placeholder="Акт / Счёт"></div><div class="filter"><label>Источник</label><select id="docSource"><option value="">Все</option>${['manual','bitrix24','1c'].map(v=>`<option ${f.source===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="filter"><label>Статус</label><select id="docSync"><option value="">Все</option><option value="synced" ${f.sync==='synced'?'selected':''}>Синхронизирован</option><option value="pending" ${f.sync==='pending'?'selected':''}>Ожидает</option><option value="error" ${f.sync==='error'?'selected':''}>Ошибка</option><option value="not_synced" ${f.sync==='not_synced'?'selected':''}>Не синхронизирован</option></select></div><div class="filter"><label>Мин. сумма</label><input id="docMin" type="number" value="${f.min}"></div></div>`}
async function renderDocuments(){const rows=await api(`/api/documents?${qsPeriod()}`),f=state.doc,q=f.q.toLowerCase();const docs=rows.filter(d=>(!q||`${d.project_name} ${d.document_type} ${d.comment||''}`.toLowerCase().includes(q))&&(!f.project||String(d.project_id)===f.project)&&(!f.type||d.document_type.toLowerCase().includes(f.type.toLowerCase()))&&(!f.source||d.source===f.source)&&(!f.sync||d.sync_status===f.sync)&&(!f.min||d.amount>=+f.min));const syn=docs.filter(d=>d.sync_status==='synced').length,pend=docs.filter(d=>d.sync_status==='pending').length,err=docs.filter(d=>d.sync_status==='error').length,quality=docs.length?syn/docs.length*100:0;$('#crumbCurrent').textContent='/ Документы';setContent(`<div class="page-head"><div><h1>Документы</h1><p>Первичка и статус синхронизации</p></div><button class="btn primary" data-add-document>+ Документ</button></div>${documentFilters()}<div class="kpis">${kpi('Документов',docs.length,'текущая выборка')}${kpi('Синхронизировано',syn,quality.toFixed(1)+'%','received')}${kpi('Ожидает',pend,'нужна обработка','warn')}${kpi('Ошибки',err,'требуют внимания','expense')}${kpi('Качество синхронизации',quality.toFixed(1)+'%','доля успешно синхронизированных')}</div>${documentTable(docs)}`);bindCommon();bindPeriod($('#docPeriod'),refresh);const mp={docQ:'q',docProject:'project',docType:'type',docSource:'source',docSync:'sync',docMin:'min'};for(const[id,k]of Object.entries(mp)){const e=$('#'+id);if(id==='docQ'||id==='docType')bindLiveFilter(e,v=>state.doc[k]=v,renderDocuments);else if(id==='docMin')bindNumericFilter(e,v=>state.doc[k]=v,renderDocuments);else e?.addEventListener('change',()=>{state.doc[k]=e.value;renderDocuments().catch(showError)})}}
function syncLabel(s){return s==='synced'?'Синхронизирован':s==='pending'?'Ожидает':s==='error'?'Ошибка':'Не синхронизирован'}
function documentTable(rows){return `<div class="panel"><div class="table-wrap"><table><thead><tr><th>Дата</th><th>Тип</th><th>Проект</th><th>Источник</th><th>Статус</th><th>Сумма</th><th>Комментарий</th></tr></thead><tbody>${rows.length?rows.map(d=>`<tr><td>${dateRu(d.document_date)}</td><td><b>${esc(d.document_type)}</b></td><td><button class="project-link" data-open-project="${d.project_id}">${esc(d.project_name||'')}</button></td><td>${esc(d.source)}</td><td><span class="pill ${d.sync_status==='synced'?'excellent':d.sync_status==='error'?'risk':'stable'}">${syncLabel(d.sync_status)}</span></td><td>${fmt.format(d.amount)}</td><td>${esc(d.comment||'—')}</td></tr>`).join(''):`<tr><td colspan="7" class="empty-cell">Документов нет.</td></tr>`}</tbody></table></div></div>`}
async function renderCategories(){const ops=await api(`/api/transactions?${qsPeriod()}`),stats={};ops.forEach(o=>{const s=stats[o.category_id]||(stats[o.category_id]={amount:0,count:0,projects:new Set(),parties:new Set()});s.amount+=o.amount;s.count++;s.projects.add(o.project_id);const c=state.categories.find(x=>x.id===o.category_id),party=c?.type==='income'?o.counterparty:c?.party_mode==='employee'?o.employee_name:o.counterparty;if(party)s.parties.add(party)});$('#crumbCurrent').textContent='/ Статьи';setContent(`<div class="page-head"><div><h1>Статьи</h1><p>Каждая статья кликабельна: от агрегата до конкретных операций</p></div><button class="btn primary" data-new-category>+ Новая статья</button></div>${periodControls('catPeriod')}<div class="grid2 category-directory-grid"><div class="panel"><div class="panel-head"><div><h2>Поступления</h2></div></div><div class="panel-body quick-list">${categoryRows(state.categories.filter(c=>c.type==='income'),stats)}</div></div><div class="panel"><div class="panel-head"><div><h2>Расходы</h2></div></div><div class="panel-body quick-list">${categoryRows(state.categories.filter(c=>c.type==='expense'),stats)}</div></div></div>`);bindCommon();bindPeriod($('#catPeriod'),refresh);$$('[data-category-drill]').forEach(card=>card.onclick=()=>openCategoryDrill(+card.dataset.categoryDrill).catch(showError))}
function categoryRows(rows,stats){const max=Math.max(1,...rows.map(c=>stats[c.id]?.amount||0));return rows.map(c=>{const s=stats[c.id]||{amount:0,count:0,projects:new Set(),parties:new Set()},binding=c.type==='income'?'Плательщики / контрагенты':c.party_mode==='employee'?`Сотрудники · ${esc(c.employee_role||'роль не настроена')}`:'Контрагенты',tone=c.type==='income'?'good':'warn';return `<button type="button" class="category-drill-card" data-category-drill="${c.id}"><div class="category-card-head"><div><b>${esc(c.name)}</b><small>${c.is_default?'Системная статья':'Пользовательская'} · ${binding}</small></div><span class="category-arrow">→</span></div><div class="category-card-foot"><span>${s.count} ${pluralRu(s.count,'операция','операции','операций')} · ${s.projects.size} ${pluralRu(s.projects.size,'проект','проекта','проектов')}</span><strong class="${tone}">${fmt.format(s.amount)}</strong></div><div class="track"><i class="fill ${c.type==='income'?'good':'warn'}" style="width:${progress(s.amount,max)}%"></i></div></button>`}).join('')||'<div class="muted">Нет статей</div>'}
function categoryPartyName(category,op){if(category.type==='income')return op.counterparty||'Плательщик не указан';if(category.party_mode==='employee')return op.employee_name||'Сотрудник не указан';return op.counterparty||'Контрагент не указан'}
function categoryBreakdownList(rows,total,tone='warn'){if(!rows.length)return '<div class="category-empty">Нет данных за выбранный период.</div>';const max=Math.max(1,...rows.map(x=>x.amount));return `<div class="category-breakdown-list">${rows.map(x=>`<div class="category-breakdown-item"><div class="category-breakdown-main"><b>${esc(x.name)}</b><small>${x.count} ${pluralRu(x.count,'операция','операции','операций')} · ${(x.amount/Math.max(1,total)*100).toFixed(1)}%</small><div class="track"><i class="fill ${tone}" style="width:${progress(x.amount,max)}%"></i></div></div><strong class="${tone==='good'?'good':'bad'}">${fmt.format(x.amount)}</strong></div>`).join('')}</div>`}
async function openCategoryDrill(id){const category=state.categories.find(c=>c.id===id);if(!category)throw new Error('Статья не найдена');const all=await api(`/api/transactions?${qsPeriod()}`),rows=all.filter(o=>o.category_id===id),total=rows.reduce((s,o)=>s+o.amount,0),projects=new Map(),parties=new Map();for(const o of rows){const party=categoryPartyName(category,o),pa=parties.get(party)||{name:party,amount:0,count:0};pa.amount+=o.amount;pa.count++;parties.set(party,pa);const pr=projects.get(o.project_id)||{id:o.project_id,name:o.project_name||'Проект',amount:0,count:0};pr.amount+=o.amount;pr.count++;projects.set(o.project_id,pr)}const partyRows=[...parties.values()].sort((a,b)=>b.amount-a.amount),projectRows=[...projects.values()].sort((a,b)=>b.amount-a.amount),partyTitle=category.type==='income'?'Плательщиков':category.party_mode==='employee'?'Сотрудников':'Контрагентов',partyHead=category.type==='income'?'Кто сформировал сумму':category.party_mode==='employee'?'Кто сформировал расходы':'Кто сформировал расходы',tone=category.type==='income'?'good':'bad',sourceText=category.type==='income'?'Группировка по плательщикам / контрагентам':category.party_mode==='employee'?`Группировка по сотрудникам роли «${category.employee_role||'не настроена'}»`:'Группировка по внешним контрагентам';$('#metricTitle').textContent=category.name;$('#metricSub').textContent=`${dateRu(state.period.start)} — ${dateRu(state.period.end)} · ${rows.length} ${pluralRu(rows.length,'операция','операции','операций')}`;$('#metricBody').innerHTML=`<div class="metric-modal-shell metric-prototype category-prototype">${metricHero([metricHeroCard('Сумма по статье',fmt.format(total),category.type==='income'?'поступления выбранного периода':'расходы выбранного периода',tone),metricHeroCard('Операций',rows.length,'записей в журнале'),metricHeroCard('Проектов',projectRows.length,'затронуто статьёй'),metricHeroCard(partyTitle,partyRows.length,sourceText)])}${metricExplain('Логика детализации',`${sourceText}. Ниже сумма разложена по источникам, проектам и конкретным операциям.`)}<div class="category-analytics-grid">${metricSection(partyHead,sourceText,categoryBreakdownList(partyRows,total,category.type==='income'?'good':'warn'))}${metricSection('По проектам','Сумма статьи в разрезе проектов',projectRows.length?`<div class="category-project-list">${projectRows.map(p=>`<button type="button" class="category-project-item" data-category-project="${p.id}"><div><b>${esc(p.name)}</b><small>${p.count} ${pluralRu(p.count,'операция','операции','операций')}</small></div><strong class="${category.type==='income'?'good':'bad'}">${fmt.format(p.amount)}</strong></button>`).join('')}</div>`:'<div class="category-empty">Нет проектов за выбранный период.</div>')}</div>${metricSection('Журнал операций',`${rows.length} ${pluralRu(rows.length,'операция','операции','операций')} по статье`,metricProjectTable(rows,[{label:'Дата',render:o=>dateRu(o.transaction_date)},{label:'Проект',render:o=>`<button type="button" class="project-link" data-category-project="${o.project_id}">${esc(o.project_name||'')}</button>`},{label:category.type==='income'?'Плательщик / контрагент':category.party_mode==='employee'?'Сотрудник':'Контрагент',render:o=>esc(categoryPartyName(category,o))},{label:'Комментарий',render:o=>esc(o.comment||'—')},{label:'Сумма',cls:()=>category.type==='income'?'good metric-money':'bad metric-money',render:o=>`${category.type==='income'?'+':'−'}${fmt.format(o.amount)}`}],`По статье «${category.name}» операций за период нет.`))}</div>`;$('#metricDialog').showModal();$$('[data-category-project]',$('#metricBody')).forEach(btn=>btn.onclick=()=>{$('#metricDialog').close();openProject(+btn.dataset.categoryProject)})}
function employeeSuccess(projects){const active=projects.filter(p=>p.status==='active');return active.length?active.filter(p=>p.financial_health!=='risk').length/active.length*100:0}
function rankPosition(rows,value,key,desc=true){const sorted=[...rows].sort((a,b)=>desc?(b[key]-a[key]):(a[key]-b[key]));const idx=sorted.findIndex(x=>x.e.id===value.e.id);return idx>=0?idx+1:0}
function isoDate(d){return d.toISOString().slice(0,10)}
function rollingMonthWindows(endDate,count=5){const end=new Date(endDate+'T12:00:00Z'),out=[];for(let i=count-1;i>=0;i--){const d=new Date(Date.UTC(end.getUTCFullYear(),end.getUTCMonth()-i,1,12)),last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0,12));out.push({start:isoDate(d),end:isoDate(last),label:new Intl.DateTimeFormat('ru-RU',{month:'short'}).format(d).replace('.','')})}return out}
async function managerMonthlySeries(projectIds){const ids=new Set(projectIds),windows=rollingMonthWindows(state.period.end,5);return Promise.all(windows.map(async w=>{const data=await api(`/api/dashboard?date_from=${w.start}&date_to=${w.end}`),ps=data.projects.filter(p=>ids.has(p.id)),t=projectTotal(ps);return{...w,completed:t.completed,received:t.received,expenses:t.expenses}}))}
async function personalMonthlySeries(employeeId){const windows=rollingMonthWindows(state.period.end,5);return Promise.all(windows.map(async w=>{const rows=await api(`/api/transactions?date_from=${w.start}&date_to=${w.end}&employee_id=${employeeId}`),expenses=rows.filter(x=>x.type==='expense').reduce((s,x)=>s+x.amount,0);return{...w,expenses}}))}
function chartBars(series,keys){const max=Math.max(1,...series.flatMap(x=>keys.map(k=>Math.abs(x[k.key]||0))));return `<div class="portfolio-chart">${series.map(x=>`<div class="chart-month"><div class="chart-bars">${keys.map(k=>`<i class="chart-bar ${k.cls}" title="${k.label}: ${fmt.format(x[k.key]||0)}" style="height:${Math.max(4,progress(Math.abs(x[k.key]||0),max))}%"></i>`).join('')}</div><small>${esc(x.label)}</small></div>`).join('')}</div>`}
function successPill(value){const cls=value>=80?'good':value>=60?'blue':'bad';return `<span class="pill ${cls==='good'?'green':''}">Успешность ${value.toFixed(0)}%</span>`}

async function employeeMemberships(){const details=await Promise.all(state.projects.map(p=>getProjectDetail(p.id)));const map=new Map(state.employees.map(e=>[e.id,[]]));for(const p of details){for(const m of p.members||[]){if(map.has(m.id))map.get(m.id).push(p)}if(p.manager_employee_id&&map.has(p.manager_employee_id)&&!map.get(p.manager_employee_id).some(x=>x.id===p.id))map.get(p.manager_employee_id).push(p)}return map}
function employeeFilters(){const f=state.emp,roles=[...new Set(state.employees.map(e=>e.role).filter(Boolean))].sort();return `${periodControls('empPeriod')}<div class="filters"><div class="filter"><label>Поиск</label><input id="empQ" class="search" placeholder="Сотрудник, роль, email" value="${esc(f.q)}"></div><div class="filter"><label>Роль</label><select id="empRole"><option value="">Все</option>${roles.map(r=>`<option ${f.role===r?'selected':''}>${esc(r)}</option>`).join('')}</select></div><div class="filter"><label>Сортировка</label><select id="empSort"><option value="success" ${f.sort==='success'?'selected':''}>Успешность ↓</option><option value="projects" ${f.sort==='projects'?'selected':''}>Активные проекты</option><option value="profit" ${f.sort==='profit'?'selected':''}>Прибыль управляемого портфеля</option><option value="personal" ${f.sort==='personal'?'selected':''}>Персональные расходы</option><option value="name" ${f.sort==='name'?'selected':''}>Имя</option></select></div></div>`}
async function buildEmployeeRows(){const [memberships,periodTransactions]=await Promise.all([employeeMemberships(),api(`/api/transactions?${qsPeriod()}`)]),expenseRows=periodTransactions.filter(x=>x.type==='expense'&&x.employee_id),expenseByEmployee=new Map();for(const x of expenseRows){if(!expenseByEmployee.has(x.employee_id))expenseByEmployee.set(x.employee_id,[]);expenseByEmployee.get(x.employee_id).push(x)}const rows=state.employees.map(e=>{const ps=memberships.get(e.id)||[],managed=ps.filter(p=>p.manager_employee_id===e.id),personalExpenses=expenseByEmployee.get(e.id)||[],personalTotal=personalExpenses.reduce((s,x)=>s+x.amount,0),managedTotal=projectTotal(managed),activeProjects=ps.filter(p=>p.status==='active'),success=employeeSuccess(ps),isManager=managed.length>0;return{e,ps,managed,personalExpenses,personalTotal,managedTotal,activeProjects,success,isManager}});return{rows,memberships,expenseByEmployee}}
async function openEmployeeDetail(id){state.currentEmployeeId=id;state.view='employeeDetail';await render()}
async function renderEmployees(){const data=await buildEmployeeRows(),q=state.emp.q.toLowerCase();let rows=data.rows.filter(x=>(!q||`${x.e.name} ${x.e.email} ${x.e.role}`.toLowerCase().includes(q))&&(!state.emp.role||x.e.role===state.emp.role));rows.sort((a,b)=>state.emp.sort==='success'?b.success-a.success:state.emp.sort==='personal'?b.personalTotal-a.personalTotal:state.emp.sort==='projects'?b.activeProjects.length-a.activeProjects.length:state.emp.sort==='name'?a.e.name.localeCompare(b.e.name,'ru'):b.managedTotal.profit-a.managedTotal.profit);const managers=rows.filter(x=>x.isManager),withActive=rows.filter(x=>x.activeProjects.length),avgSuccess=withActive.length?withActive.reduce((s,x)=>s+x.success,0)/withActive.length:0;$('#crumbCurrent').textContent='/ Сотрудники';setContent(`<div class="page-head"><div><h1>Сотрудники</h1><p>Показатели пересчитываются за выбранный период · кликните сотрудника для полной аналитики</p></div><button class="btn primary" data-add-employee>+ Новый сотрудник</button></div>${employeeFilters()}<div class="kpis employee-summary-kpis">${kpi('Сотрудников',rows.length,'текущая выборка','','data-employee-summary="employees"')}${kpi('Менеджеров',managers.length,'управляют проектами','','data-employee-summary="managers"')}${kpi('Проектов участия',rows.reduce((s,x)=>s+x.ps.length,0),'сумма назначений','','data-employee-summary="assignments"')}${kpi('Персональных расходов',fmt.format(rows.reduce((s,x)=>s+x.personalTotal,0)),'по операциям сотрудников','expense','data-employee-summary="personal"')}${kpi('Средняя успешность',avgSuccess.toFixed(0)+'%','по активным проектам','received','data-employee-summary="success"')}</div><div class="portfolio-note" style="margin:10px 0"><div><b>Успешность проектов участия</b>Это характеристика финансового состояния активных проектов в выбранном периоде, а не субъективная оценка сотрудника.</div></div><div class="panel employee-directory"><div class="table-wrap"><table><thead><tr><th>Сотрудник</th><th>Роль</th><th>Активных проектов</th><th>Успешность</th><th>Загрузка</th><th>Персональные расходы</th><th>Прибыль управляемого портфеля</th><th></th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr class="employee-row" data-employee="${x.e.id}"><td><div style="display:flex;gap:8px;align-items:center"><div class="avatar">${initials(x.e.name)}</div><div><b>${esc(x.e.name)}</b><div class="muted" style="font-size:8px">${esc(x.e.email||'')}</div></div></div></td><td>${esc(x.e.role||'—')}</td><td><b>${x.activeProjects.length}</b><div class="mini-stat">из ${x.ps.length} проектов</div></td><td><div class="progress-stat"><b>${x.success.toFixed(0)}%</b><div class="track"><i class="fill ${x.success>=80?'good':x.success>=60?'blue':'bad'}" style="width:${x.success}%"></i></div></div></td><td><div class="progress-stat"><b>${x.activeProjects.length}/${Math.max(1,x.ps.length)}</b><div class="track"><i class="fill warn" style="width:${progress(x.activeProjects.length,Math.max(1,x.ps.length))}%"></i></div></div></td><td>${x.personalTotal?`<button class="link-btn bad" data-employee-personal="${x.e.id}">${fmt.format(x.personalTotal)}</button>`:'0,00 ₽'}</td><td>${x.isManager?`<button class="link-btn ${x.managedTotal.profit<0?'bad':'good'}" data-employee-managed-profit="${x.e.id}">${fmt.format(x.managedTotal.profit)}</button>`:'—'}</td><td><button class="btn small ghost employee-open" data-employee-open="${x.e.id}">Аналитика →</button></td></tr>`).join(''):`<tr><td colspan="8" class="empty-cell">Сотрудников нет.</td></tr>`}</tbody></table></div></div>`);bindCommon();bindPeriod($('#empPeriod'),refresh);bindLiveFilter($('#empQ'),v=>state.emp.q=v,renderEmployees);$('#empRole').onchange=()=>{state.emp.role=$('#empRole').value;renderEmployees().catch(showError)};$('#empSort').onchange=()=>{state.emp.sort=$('#empSort').value;renderEmployees().catch(showError)};$$('[data-employee]').forEach(r=>r.onclick=e=>{if(e.target.closest('button'))return;openEmployeeDetail(+r.dataset.employee).catch(showError)});$$('[data-employee-open]').forEach(x=>x.onclick=e=>{e.stopPropagation();openEmployeeDetail(+x.dataset.employeeOpen).catch(showError)});$$('[data-employee-summary]').forEach(x=>x.onclick=()=>openEmployeeSummaryDrill(x.dataset.employeeSummary,rows,data.memberships,data.expenseByEmployee));$$('[data-employee-personal]').forEach(x=>x.onclick=ev=>{ev.stopPropagation();const row=rows.find(r=>r.e.id===+x.dataset.employeePersonal);if(row)openEmployeeParticipantMetric('personal',row.e,row.ps,row.personalExpenses)});$$('[data-employee-managed-profit]').forEach(x=>x.onclick=ev=>{ev.stopPropagation();const row=rows.find(r=>r.e.id===+x.dataset.employeeManagedProfit);if(row)openPortfolioMetric('profit',row.managed,`Управляемый портфель · ${row.e.name}`)})}
async function renderEmployeeDetail(){const id=state.currentEmployeeId,e=state.employees.find(x=>x.id===id);if(!e){state.view='employees';return renderEmployees()}const data=await buildEmployeeRows(),row=data.rows.find(x=>x.e.id===id),ps=row.ps,managed=row.managed,isManager=row.isManager,personalExpenses=row.personalExpenses,success=row.success;$('#crumbCurrent').textContent='/ '+e.name;const back=`<div class="muted" style="font-size:10px">← <a href="#" id="employeeBack" style="color:inherit;text-decoration:none">Вернуться к сотрудникам</a></div>`;if(isManager){const managerRows=data.rows.filter(x=>x.isManager).map(x=>({...x,profitRank:x.managedTotal.profit,rentRank:totalRent(x.managedTotal),successRank:employeeSuccess(x.managed)})),me=managerRows.find(x=>x.e.id===e.id),profitPos=rankPosition(managerRows,me,'profitRank'),successPos=rankPosition(managerRows,me,'successRank'),rentPos=rankPosition(managerRows,me,'rentRank'),t=projectTotal(managed),rent=totalRent(t),series=await managerMonthlySeries(managed.map(p=>p.id)),health={excellent:managed.filter(p=>p.financial_health==='excellent').length,stable:managed.filter(p=>p.financial_health==='stable').length,risk:managed.filter(p=>p.financial_health==='risk').length};setContent(`${back}<div class="employee-detail-head"><div class="avatar">${initials(e.name)}</div><div class="employee-detail-meta"><h1>${esc(e.name)}</h1><p>${esc(e.role||'Менеджер проекта')} · ${esc(e.email||'')}</p></div><div style="margin-left:auto" class="inline-actions">${successPill(employeeSuccess(managed))}<button class="btn small" data-edit-employee="${e.id}">Редактировать</button></div></div><div class="panel" style="margin-top:12px">${periodControls('employeeDetailPeriod')}</div><div class="portfolio-note" style="margin-top:10px"><div><b>Портфель менеджера</b>В расчёт входят только проекты, где сотрудник назначен менеджером. Все финансовые показатели пересчитываются по выбранному периоду.</div></div><div class="manager-ranks"><div class="rank-card"><small>Место по прибыли</small><b>#${profitPos}</b><span>из ${managerRows.length} менеджеров</span></div><div class="rank-card"><small>Место по успешности</small><b>#${successPos}</b><span>из ${managerRows.length} менеджеров</span></div><div class="rank-card"><small>Место по рентабельности</small><b>#${rentPos}</b><span>из ${managerRows.length} менеджеров</span></div></div><div class="kpis employee-detail-kpis">${kpi('Активных проектов',managed.filter(p=>p.status==='active').length,`из ${managed.length} проектов`,'','data-employee-detail-metric="projects"')}${kpi('Сумма сделок',fmt.format(t.deal),'по датам сделок','','data-portfolio-metric="deal"')}${kpi('Выполнено',fmt.format(t.completed),'за выбранный период','blue','data-portfolio-metric="completed"')}${kpi('Получено',fmt.format(t.received),'за выбранный период','received','data-portfolio-metric="received"')}${kpi('Расходы',fmt.format(t.expenses),'за выбранный период','expense','data-portfolio-metric="expenses"')}${kpi('Прибыль',fmt.format(t.profit),'Выполнено − Расходы','','data-portfolio-metric="profit"')}${kpi('Рентабельность',rent.toFixed(1)+'%','прибыль / выполнено × 100%','','data-portfolio-metric="profitability"')}${kpi('Общая дебиторка',fmt.format(t.receivable),'по проектам сотрудника','warn','data-portfolio-metric="receivable"')}</div><div class="grid2" style="margin-top:12px"><div class="panel"><div class="panel-head"><div><h2>Финансовая динамика портфеля</h2><p>Выполнено · Получено · Расходы за последние 5 месяцев</p></div><div class="chart-legend"><span class="blue">● Выполнено</span><span class="good">● Получено</span><span class="bad">● Расходы</span></div></div><div class="panel-body">${chartBars(series,[{key:'completed',label:'Выполнено',cls:'blue'},{key:'received',label:'Получено',cls:'good'},{key:'expenses',label:'Расходы',cls:'bad'}])}</div></div><div class="panel"><div class="panel-head"><div><h2>Финансовое состояние проектов</h2><p>Нажмите на группу для расшифровки</p></div></div><div class="panel-body manager-health">${['excellent','stable','risk'].map(h=>`<div class="manager-health-card" data-employee-health="${h}"><div class="top"><b class="${h==='excellent'?'good':h==='risk'?'bad':'blue'}">${healthText(h)}</b><strong>${health[h]}</strong></div><small>${healthMicro(h)}</small><div class="track"><i class="fill ${h==='excellent'?'good':h==='risk'?'bad':'blue'}" style="width:${progress(health[h],Math.max(1,managed.length))}%"></i></div></div>`).join('')}</div></div></div><div class="panel manager-project-table" style="margin-top:12px"><div class="panel-head"><div><h2>Проекты сотрудника</h2><p>${managed.length} проектов · все показатели за выбранный период</p></div></div>${employeeManagerProjectTable(managed)}</div>`)}else{const series=await personalMonthlySeries(e.id),health={excellent:ps.filter(p=>p.financial_health==='excellent').length,stable:ps.filter(p=>p.financial_health==='stable').length,risk:ps.filter(p=>p.financial_health==='risk').length};setContent(`${back}<div class="employee-detail-head"><div class="avatar">${initials(e.name)}</div><div class="employee-detail-meta"><h1>${esc(e.name)}</h1><p>${esc(e.role||'Сотрудник')} · ${esc(e.email||'')}</p></div><div style="margin-left:auto" class="inline-actions">${successPill(success)}<button class="btn small" data-edit-employee="${e.id}">Редактировать</button></div></div><div class="panel" style="margin-top:12px">${periodControls('employeeDetailPeriod')}</div><div class="portfolio-note" style="margin-top:10px"><div><b>Аналитика участника проекта</b>Финансовая экономика всего проекта сотруднику не приписывается. Показываются проекты участия и персональные расходы, связанные с ним напрямую.</div></div><div class="kpis employee-detail-kpis participant">${kpi('Проектов участия',ps.length,'всего назначений','','data-employee-metric="projects"')}${kpi('Активных проектов',row.activeProjects.length,'статус «В работе»','','data-employee-metric="active"')}${kpi('Успешность',success.toFixed(0)+'%','активные проекты без статуса «Риск»','received','data-employee-detail-metric="success"')}${kpi('Персональные расходы',fmt.format(row.personalTotal),'только операции сотрудника','expense','data-employee-metric="personal"')}${kpi('Операций расходов',personalExpenses.length,'за выбранный период','','data-employee-metric="expenseOps"')}</div><div class="grid2" style="margin-top:12px"><div class="panel"><div class="panel-head"><div><h2>Динамика персональных расходов</h2><p>Последние 5 месяцев</p></div></div><div class="panel-body">${chartBars(series,[{key:'expenses',label:'Персональные расходы',cls:'bad'}])}</div></div><div class="panel"><div class="panel-head"><div><h2>Финансовое состояние проектов участия</h2><p>Характеристика проектов, не оценка сотрудника</p></div></div><div class="panel-body manager-health">${['excellent','stable','risk'].map(h=>`<div class="manager-health-card" data-employee-health="${h}"><div class="top"><b class="${h==='excellent'?'good':h==='risk'?'bad':'blue'}">${healthText(h)}</b><strong>${health[h]}</strong></div><small>${healthMicro(h)}</small><div class="track"><i class="fill ${h==='excellent'?'good':h==='risk'?'bad':'blue'}" style="width:${progress(health[h],Math.max(1,ps.length))}%"></i></div></div>`).join('')}</div></div></div><div class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Проекты сотрудника</h2><p>${ps.length} проектов участия</p></div></div>${employeeParticipantProjectTable(ps,e)}</div><div class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Персональные расходы</h2><p>Только операции, где сотрудник указан исполнителем расхода</p></div></div>${employeeExpenseDrillTable(personalExpenses).replace('<div class="panel">','').replace(/<\/div>$/,'')}</div>`)}$('#employeeBack').onclick=ev=>{ev.preventDefault();state.view='employees';state.currentEmployeeId=null;render().catch(showError)};bindPeriod($('#employeeDetailPeriod'),refresh);$$('[data-portfolio-metric]').forEach(x=>x.onclick=()=>openPortfolioMetric(x.dataset.portfolioMetric,managed,`Управляемый портфель · ${e.name}`));$$('[data-employee-metric]').forEach(x=>x.onclick=()=>openEmployeeParticipantMetric(x.dataset.employeeMetric,e,ps,personalExpenses));$$('[data-employee-detail-metric="projects"]').forEach(x=>x.onclick=()=>metricDialog('Активные проекты',`${e.name} · ${dateRu(state.period.start)} — ${dateRu(state.period.end)}`,employeeProjectsDrillTable((isManager?managed:ps).filter(p=>p.status==='active'),e)));$$('[data-employee-detail-metric="success"]').forEach(x=>x.onclick=()=>metricDialog('Успешность проектов участия',`${e.name} · ${success.toFixed(0)}%`,employeeProjectsDrillTable(ps.filter(p=>p.status==='active'),e)));$$('[data-employee-health]').forEach(x=>x.onclick=()=>openEmployeeHealthDrill(isManager?managed:ps,x.dataset.employeeHealth,e));$$('[data-open-project]').forEach(x=>x.onclick=()=>openProject(+x.dataset.openProject));$$('[data-analytics-project]').forEach(x=>x.onclick=()=>openProject(+x.dataset.analyticsProject));$$('[data-edit-employee]').forEach(x=>x.onclick=()=>openEmployeeEditDialog(+x.dataset.editEmployee))}
function employeeManagerProjectTable(projects){return `<div class="table-wrap"><table><thead><tr><th>Проект</th><th>Статус</th><th>Состояние</th><th>Сумма сделки</th><th>Выполнено</th><th>Получено</th><th>Расходы</th><th>Прибыль</th><th>Рентабельность</th><th>Дебиторка</th></tr></thead><tbody>${projects.map(p=>`<tr class="click-row" data-open-project="${p.id}"><td><b>${esc(p.name)}</b><div class="mini-stat">${esc(p.client||'')}</div></td><td>${statusPill(p)}</td><td>${healthPill(p)}</td><td>${fmt.format(p.deal_amount_period||0)}</td><td class="blue">${fmt.format(p.completed)}</td><td class="good">${fmt.format(p.received)}</td><td class="bad">${fmt.format(p.expenses)}</td><td class="${p.profit<0?'bad':'good'}">${fmt.format(p.profit)}</td><td>${p.profitability.toFixed(1)}%</td><td class="${p.receivable?'warn':''}">${fmt.format(p.receivable)}</td></tr>`).join('')||'<tr><td colspan="10" class="empty-cell">Проектов нет.</td></tr>'}</tbody></table></div>`}
function employeeParticipantProjectTable(projects,e){return `<div class="table-wrap"><table><thead><tr><th>Проект</th><th>Клиент</th><th>Роль</th><th>Статус</th><th>Фин. состояние</th><th></th></tr></thead><tbody>${projects.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.client||'—')}</td><td>${esc(employeeProjectRole(p,e))}</td><td>${statusText(p.status)}</td><td>${healthText(p.financial_health)}</td><td><button class="btn small ghost" data-open-project="${p.id}">Открыть →</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty-cell">Проектов нет.</td></tr>'}</tbody></table></div>`}
function openEmployeeHealthDrill(projects,key,e){const list=projects.filter(p=>p.financial_health===key);renderHealthDrill(list,key,{title:`Финансовое состояние «${healthText(key)}» — ${list.length} ${pluralRu(list.length,'проект','проекта','проектов')}`,subtitle:`${e.name} · ${dateRu(state.period.start)} — ${dateRu(state.period.end)}`})}
function employeeProjectRole(p,e){const member=(p.members||[]).find(m=>m.id===e.id);return member?.role||member?.employee_role||(p.manager_employee_id===e.id?'Менеджер проекта':e.role||'Участник')}
function employeeProjectsDrillTable(projects,e){return `<div class="panel"><div class="table-wrap"><table><thead><tr><th>Проект</th><th>Клиент</th><th>Роль в проекте</th><th>Статус</th><th>Фин. состояние</th><th></th></tr></thead><tbody>${projects.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.client||'—')}</td><td>${esc(employeeProjectRole(p,e))}</td><td>${statusText(p.status)}</td><td>${healthText(p.financial_health)}</td><td>${projectOpenButton(p.id)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty-cell">Проектов нет.</td></tr>'}</tbody></table></div></div>`}
function employeeExpenseDrillTable(expenses){return `<div class="panel"><div class="table-wrap"><table><thead><tr><th>Дата</th><th>Проект</th><th>Статья</th><th>Комментарий</th><th>Сумма</th></tr></thead><tbody>${expenses.map(x=>`<tr><td>${dateRu(x.transaction_date)}</td><td><button class="link-btn" data-open-project="${x.project_id}">${esc(x.project_name)}</button></td><td>${esc(x.category_name)}</td><td>${esc(x.comment||'—')}</td><td class="bad">${fmt.format(x.amount)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-cell">Персональных расходов за период нет.</td></tr>'}</tbody></table></div></div>`}
function openEmployeeParticipantMetric(type,e,ps,personalExpenses){const active=ps.filter(p=>p.status==='active'),personalTotal=personalExpenses.reduce((s,x)=>s+x.amount,0),period=`${dateRu(state.period.start)} — ${dateRu(state.period.end)}`;let title='',sub=`${e.name} · ${period}`,body='';if(type==='projects'){title='Проекты участия';body=employeeProjectsDrillTable(ps,e)}else if(type==='active'){title='Активные проекты';body=employeeProjectsDrillTable(active,e)}else if(type==='personal'||type==='expenseOps'){title=type==='personal'?'Персональные расходы':'Операции персональных расходов';sub=`${e.name} · ${personalExpenses.length} операций · ${period}`;body=employeeExpenseDrillTable(personalExpenses)}else{title='Сводка периода';body=`<div class="metric-grid">${kpi('Проектов участия',ps.length,'всего назначений')}${kpi('Активных проектов',active.length,'статус «В работе»')}${kpi('Персональные расходы',fmt.format(personalTotal),'операции сотрудника','expense')}${kpi('Операций расходов',personalExpenses.length,'за период')}</div><div class="info-callout"><b>Период аналитики</b>${period}. Финансовая экономика проектов участнику не приписывается; учитываются только его проектные назначения и персональные расходы.</div>`}metricDialog(title,sub,body)}
function openEmployeeSummaryDrill(type,rows,memberships,expenseByEmployee){const period=`${dateRu(state.period.start)} — ${dateRu(state.period.end)}`,managers=rows.filter(x=>x.isManager),assignments=rows.flatMap(x=>x.ps.map(p=>({employee:x.e,project:p,role:employeeProjectRole(p,x.e),isManager:p.manager_employee_id===x.e.id}))),expenses=rows.flatMap(x=>x.personalExpenses.map(op=>({employee:x.e,op})));let title='',sub=period,body='';if(type==='employees'||type==='managers'){const source=type==='managers'?managers:rows;title=type==='managers'?'Менеджеры':'Сотрудники';body=`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Сотрудник</th><th>Роль</th><th>Проекты</th><th>Тип аналитики</th><th>Персональные расходы</th><th>Управляемая прибыль</th><th></th></tr></thead><tbody>${source.map(x=>`<tr><td><b>${esc(x.e.name)}</b><div class="muted">${esc(x.e.email||'')}</div></td><td>${esc(x.e.role||'—')}</td><td>${x.isManager?`${x.managed.length} управл. · ${x.ps.length} всего`:`${x.ps.length} участия`}</td><td>${x.isManager?'Менеджер портфеля':'Участник проекта'}</td><td class="bad">${fmt.format(x.personalTotal)}</td><td>${x.isManager?fmt.format(x.managedTotal.profit):'—'}</td><td><button class="btn small ghost" data-open-employee="${x.e.id}">Открыть →</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-cell">Нет сотрудников.</td></tr>'}</tbody></table></div></div>`}else if(type==='assignments'){title='Проекты участия';body=`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Сотрудник</th><th>Проект</th><th>Роль</th><th>Связь</th><th>Статус</th><th></th></tr></thead><tbody>${assignments.map(x=>`<tr><td><button class="link-btn" data-open-employee="${x.employee.id}">${esc(x.employee.name)}</button></td><td><button class="link-btn" data-open-project="${x.project.id}">${esc(x.project.name)}</button></td><td>${esc(x.role)}</td><td>${x.isManager?'Управление':'Участие'}</td><td>${statusText(x.project.status)}</td><td>${projectOpenButton(x.project.id)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty-cell">Назначений нет.</td></tr>'}</tbody></table></div></div>`}else if(type==='personal'){title='Персональные расходы сотрудников';body=`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Дата</th><th>Сотрудник</th><th>Проект</th><th>Статья</th><th>Комментарий</th><th>Сумма</th></tr></thead><tbody>${expenses.map(x=>`<tr><td>${dateRu(x.op.transaction_date)}</td><td><button class="link-btn" data-open-employee="${x.employee.id}">${esc(x.employee.name)}</button></td><td><button class="link-btn" data-open-project="${x.op.project_id}">${esc(x.op.project_name)}</button></td><td>${esc(x.op.category_name)}</td><td>${esc(x.op.comment||'—')}</td><td class="bad">${fmt.format(x.op.amount)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty-cell">Персональных расходов нет.</td></tr>'}</tbody></table></div></div>`}else if(type==='success'){title='Средняя успешность';const activeRows=rows.filter(x=>x.activeProjects?.length),avg=activeRows.length?activeRows.reduce((s,x)=>s+x.success,0)/activeRows.length:0;body=`<div class="metric-grid">${kpi('Средняя успешность',avg.toFixed(0)+'%','по активным проектам','received')}${kpi('Сотрудников с активными проектами',activeRows.length,'в текущей выборке')}${kpi('Активных проектов',activeRows.reduce((s,x)=>s+x.activeProjects.length,0),'сумма назначений')}</div><div class="info-callout"><b>Как считается</b>Для каждого сотрудника берутся активные проекты участия. Проект считается успешным, если его финансовое состояние не «Риск». Это характеристика проектов, а не субъективная оценка человека.</div>`}else{title='Сводка сотрудников';const personalTotal=rows.reduce((s,x)=>s+x.personalTotal,0);body=`<div class="metric-grid">${kpi('Сотрудников',rows.length,'текущая выборка')}${kpi('Менеджеров',managers.length,'управляют проектами')}${kpi('Проектов участия',assignments.length,'сумма назначений')}${kpi('Персональных расходов',fmt.format(personalTotal),'операции сотрудников','expense')}</div><div class="info-callout"><b>Период</b>${period}. Все значения учитывают текущие фильтры раздела «Сотрудники».</div>`}metricDialog(title,sub,body);$$('#metricBody [data-open-employee]').forEach(x=>x.onclick=()=>{$('#metricDialog').close();openEmployeeDetail(+x.dataset.openEmployee).catch(showError)})}

function metricDialog(title,sub,body){const dlg=$('#metricDialog');$('#metricTitle').textContent=title;$('#metricSub').textContent=sub;$('#metricBody').innerHTML=body;dlg.showModal();dlg.scrollTop=0;$$('#metricBody [data-open-project]').forEach(x=>x.onclick=()=>{dlg.close();openProject(+x.dataset.openProject)});$$('#metricBody [data-debt]').forEach(x=>x.onclick=e=>{e.stopPropagation();dlg.close();openDebt(+x.dataset.debt)});$$('#metricBody [data-apply-health-filter]').forEach(x=>x.onclick=()=>{state.filters.health=x.dataset.applyHealthFilter;dlg.close();renderDashboard().catch(showError)})}
function healthRuleText(key){return key==='excellent'?'Прибыль положительная, рентабельность ≥ 50%, общая дебиторка ≤ 25% выполнения.':key==='stable'?'Критических значений нет, но рентабельность 20–49,9% или дебиторка 25–35%.':'Хотя бы один фактор критичен: прибыль < 0, рентабельность < 20% или дебиторка > 35%.'}
function healthTone(key){return key==='excellent'?'good':key==='risk'?'bad':'blue'}
function healthMetricState(type,p){return type==='profit'?(p.profit<0?'risk':'excellent'):type==='profitability'?(p.profitability<20?'risk':p.profitability>=50?'excellent':'stable'):(p.debt_ratio>35?'risk':p.debt_ratio<=25?'excellent':'stable')}
function healthMetricHint(type,state){if(type==='profit')return state==='risk'?'Прибыль ниже 0 ₽':'Прибыль положительная';if(type==='profitability')return state==='excellent'?'Отлично: ≥ 50%':state==='stable'?'Допустимо: 20–49,9%':'Риск: < 20%';return state==='excellent'?'Отлично: ≤ 25%':state==='stable'?'Допустимо: 25–35%':'Риск: > 35%'}
function healthMetricBox(label,value,state,note){const tone=healthTone(state);return `<div class="health-metric-card ${tone}"><div class="health-metric-label">${label}</div><div class="health-metric-value ${tone}">${value}</div><small>${note}</small></div>`}
function healthGuideCards(activeKey){return `<div class="health-rule-grid">${['excellent','stable','risk'].map(key=>`<div class="health-rule-card ${healthTone(key)} ${key===activeKey?'active':''}"><b class="${healthTone(key)}">${healthText(key)}</b><small>${healthRuleText(key)}</small></div>`).join('')}</div>`}
function healthProjectCard(p,activeKey){const profitState=healthMetricState('profit',p),rentState=healthMetricState('profitability',p),debtState=healthMetricState('receivable',p),manager=p.manager?.name||'Не назначен';return `<section class="health-project-card"><div class="health-project-head"><div><h4>${esc(p.name)}</h4><p>${esc(p.client||'Без клиента')} · менеджер ${esc(manager)}</p></div><span class="pill ${activeKey}">${healthText(activeKey)}</span></div><div class="health-project-metrics">${healthMetricBox('Прибыль',fmt.format(p.profit),profitState,healthMetricHint('profit',profitState))}${healthMetricBox('Рентабельность',p.profitability.toFixed(1)+'%',rentState,healthMetricHint('profitability',rentState))}${healthMetricBox('Общая дебиторка проекта',`${fmt.format(p.receivable)} · ${p.debt_ratio.toFixed(1)}%`,debtState,healthMetricHint('receivable',debtState))}</div><div class="health-project-actions"><button class="btn small" data-debt="${p.id}">Расшифровать дебиторку</button><button class="btn small" data-open-project="${p.id}">Открыть проект</button></div></section>`}
function renderHealthDrill(list,key,options={}){const countText=`${list.length} ${pluralRu(list.length,'проект','проекта','проектов')}`,title=options.title||`Финансовое состояние «${healthText(key)}» — ${countText}`,sub=options.subtitle||'Финансовое состояние не зависит от операционного статуса «В работе / На паузе / Требует внимания».',footer=options.filterAction?`<div class="health-drill-footer"><button class="btn primary small" data-apply-health-filter="${key}">${options.filterAction}</button></div>`:'';metricDialog(title,sub,`<div class="health-drill">${healthGuideCards(key)}<div class="health-project-list">${list.map(p=>healthProjectCard(p,key)).join('')||'<div class="metric-empty">Проектов в этой группе нет.</div>'}</div>${footer}</div>`)}
function metricHeroCard(label,value,sub='',tone=''){return `<div class="metric-hero-card ${tone}"><div class="metric-hero-label">${label}</div><div class="metric-hero-value ${tone}">${value}</div><small>${sub}</small></div>`}
function metricHero(cards){return `<div class="metric-hero-grid">${cards.join('')}</div>`}
function metricExplain(title,text){return `<div class="metric-explainer"><b>${title}</b><span>${text}</span></div>`}
function metricSection(title,sub,body){return `<section class="metric-detail-section"><div class="metric-detail-head"><div><h4>${title}</h4>${sub?`<p>${sub}</p>`:''}</div></div>${body}</section>`}
function metricProjectTable(rows,columns,empty='Нет данных.'){return `<div class="metric-table-wrap"><table class="metric-detail-table"><thead><tr>${columns.map(c=>`<th>${c.label}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${columns.map(c=>`<td class="${c.cls?c.cls(row):''}">${c.render(row)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${columns.length}" class="empty-cell">${empty}</td></tr>`}</tbody></table></div>`}
function projectOpenButton(id,label='Открыть проект'){return `<button type="button" class="btn small metric-open-project" data-open-project="${id}">${label}</button>`}
function uniqueCount(rows,key){return new Set(rows.map(x=>x[key]).filter(Boolean)).size}
async function openPortfolioMetric(type,scopeProjects=null,scopeLabel=''){
  const list=scopeProjects||filteredProjects(),ids=new Set(list.map(p=>p.id)),period=`${dateRu(state.period.start)} — ${dateRu(state.period.end)}`;
  const t=projectTotal(list),completedCum=list.reduce((s,p)=>s+(p.completed_cumulative||0),0),receivedCum=list.reduce((s,p)=>s+(p.received_cumulative||0),0),newDebt=list.reduce((s,p)=>s+(p.new_receivable||0),0),debtRatio=completedCum?Math.max(0,completedCum-receivedCum)/completedCum*100:0;
  let title='',sub=scopeLabel?`${scopeLabel} · ${period}`:period,body='';
  if(type==='deal'){
    const rows=list.filter(p=>p.deal_date&&p.deal_date>=state.period.start&&p.deal_date<=state.period.end),avg=rows.length?rows.reduce((s,p)=>s+(p.deal_amount||0),0)/rows.length:0;
    title='Сумма сделок за период';
    body=`${metricHero([metricHeroCard('Сумма сделок',fmt.format(t.deal),'по дате сделки','good'),metricHeroCard('Сделок',rows.length,'в выбранной выборке','blue'),metricHeroCard('Средняя сделка',fmt.format(avg),'сумма / количество'),metricHeroCard('Проектов в выборке',list.length,'после текущих фильтров')])}${metricExplain('Как считается','Сделка попадает в показатель только если дата сделки находится внутри выбранного периода. Дальнейшее выполнение проекта на сумму сделки не влияет.')}${metricSection('Сделки в периоде','Кликните «Открыть проект» для полной карточки',metricProjectTable(rows,[{label:'Дата',render:p=>dateRu(p.deal_date)},{label:'Проект',render:p=>`<b>${esc(p.name)}</b><div class="muted">${esc(p.client||'')}</div>`},{label:'Менеджер',render:p=>esc(p.manager?.name||'Не назначен')},{label:'Сумма',cls:()=> 'metric-money',render:p=>fmt.format(p.deal_amount)},{label:'',render:p=>projectOpenButton(p.id)}],'Сделок в выбранном периоде нет.'))}`;
  }else if(type==='completed'){
    const rows=(await api(`/api/completions?${qsPeriod()}`)).filter(x=>ids.has(x.project_id)),sum=rows.reduce((s,x)=>s+x.amount,0),projects=uniqueCount(rows,'project_id'),avg=rows.length?sum/rows.length:0;
    title='Выполнено';
    body=`${metricHero([metricHeroCard('Выполнено',fmt.format(sum),'закрытые работы периода','blue'),metricHeroCard('Закрытий',rows.length,'актов / этапов'),metricHeroCard('Проектов',projects,'с выполнением в периоде'),metricHeroCard('Среднее закрытие',fmt.format(avg),'в среднем на запись')])}${metricExplain('Смысл показателя','Выполнено — стоимость фактически закрытых и принятых работ. Именно от Выполнено считаются прибыль и рентабельность.')}${metricSection('Как сформировалось выполнение','Все закрытия в выбранном периоде',metricProjectTable(rows,[{label:'Дата',render:x=>dateRu(x.completion_date)},{label:'Проект',render:x=>`<button class="link-btn" data-open-project="${x.project_id}">${esc(list.find(p=>p.id===x.project_id)?.name||'Проект')}</button>`},{label:'Основание',render:x=>esc(x.document||'—')},{label:'Комментарий',render:x=>esc(x.comment||'—')},{label:'Сумма',cls:()=> 'blue metric-money',render:x=>fmt.format(x.amount)}],'Выполнений нет.'))}`;
  }else if(type==='received'){
    const rows=(await api(`/api/transactions?${qsPeriod()}`)).filter(x=>ids.has(x.project_id)&&x.type==='income'),sum=rows.reduce((s,x)=>s+x.amount,0),payers=uniqueCount(rows,'counterparty'),projects=uniqueCount(rows,'project_id');
    title='Получено';
    body=`${metricHero([metricHeroCard('Получено',fmt.format(sum),'фактические поступления','good'),metricHeroCard('Платежей',rows.length,'операций поступления'),metricHeroCard('Плательщиков',payers,'уникальных контрагентов'),metricHeroCard('Проектов',projects,'с поступлениями в периоде')])}${metricExplain('Смысл показателя','Получено — фактический денежный поток от клиентов. Он не увеличивает прибыль напрямую: поступления уменьшают дебиторскую задолженность.')}${metricSection('Поступления за период','Каждый платёж хранит своего плательщика / контрагента',metricProjectTable(rows,[{label:'Дата',render:x=>dateRu(x.transaction_date)},{label:'Проект',render:x=>`<button class="link-btn" data-open-project="${x.project_id}">${esc(x.project_name)}</button>`},{label:'Плательщик / контрагент',render:x=>esc(x.counterparty||'—')},{label:'Статья',render:x=>esc(x.category_name)},{label:'Комментарий',render:x=>esc(x.comment||'—')},{label:'Сумма',cls:()=> 'good metric-money',render:x=>fmt.format(x.amount)}],'Поступлений нет.'))}`;
  }else if(type==='expenses'){
    const rows=(await api(`/api/transactions?${qsPeriod()}`)).filter(x=>ids.has(x.project_id)&&x.type==='expense'),sum=rows.reduce((s,x)=>s+x.amount,0),categories=uniqueCount(rows,'category_id'),projects=uniqueCount(rows,'project_id');
    const byCategory=[...rows.reduce((m,x)=>m.set(x.category_name,(m.get(x.category_name)||0)+x.amount),new Map()).entries()].sort((a,b)=>b[1]-a[1]);
    title='Расходы';
    body=`${metricHero([metricHeroCard('Расходы',fmt.format(sum),'затраты выбранного периода','bad'),metricHeroCard('Операций',rows.length,'расходных записей'),metricHeroCard('Статей',categories,'использовано в периоде'),metricHeroCard('Проектов',projects,'с расходами')])}${metricExplain('Как влияет на экономику','Расходы уменьшают прибыль проекта. Персональный расход сотрудника возникает только когда сотрудник явно указан исполнителем расходной операции.')}${metricSection('Структура расходов по статьям','Суммы агрегированы по выбранной выборке',`<div class="metric-breakdown">${byCategory.map(([name,value])=>`<div class="metric-breakdown-row"><span>${esc(name)}</span><b class="bad">${fmt.format(value)}</b></div>`).join('')||'<div class="metric-empty">Расходов нет.</div>'}</div>`)}${metricSection('Расходные операции','Детализация по проектам и контрагентам',metricProjectTable(rows,[{label:'Дата',render:x=>dateRu(x.transaction_date)},{label:'Проект',render:x=>`<button class="link-btn" data-open-project="${x.project_id}">${esc(x.project_name)}</button>`},{label:'Статья',render:x=>esc(x.category_name)},{label:'Сотрудник / контрагент',render:x=>esc(x.employee_name||x.counterparty||'—')},{label:'Комментарий',render:x=>esc(x.comment||'—')},{label:'Сумма',cls:()=> 'bad metric-money',render:x=>fmt.format(x.amount)}],'Расходов нет.'))}`;
  }else if(type==='profit'){
    const rows=[...list].sort((a,b)=>b.profit-a.profit),rent=totalRent(t),positive=rows.filter(p=>p.profit>0).length;
    title='Прибыль';
    body=`${metricHero([metricHeroCard('Выполнено',fmt.format(t.completed),'база для расчёта','blue'),metricHeroCard('Расходы',fmt.format(t.expenses),'вычитаются из выполнения','bad'),metricHeroCard('Прибыль',fmt.format(t.profit),'Выполнено − Расходы',t.profit<0?'bad':'good'),metricHeroCard('Рентабельность',rent.toFixed(1)+'%','Прибыль / Выполнено × 100%')])}${metricExplain('Формула прибыли','Прибыль = Выполнено − Расходы. Полученные деньги в прибыль напрямую не входят: они отвечают за денежный поток и дебиторку.')}${metricSection('Прибыль по проектам',`${positive} ${pluralRu(positive,'проект','проекта','проектов')} с положительной прибылью`,metricProjectTable(rows,[{label:'Проект',render:p=>`<b>${esc(p.name)}</b><div class="muted">${esc(p.client||'')}</div>`},{label:'Выполнено',cls:()=> 'blue',render:p=>fmt.format(p.completed)},{label:'Расходы',cls:()=> 'bad',render:p=>fmt.format(p.expenses)},{label:'Прибыль',cls:p=>p.profit<0?'bad metric-money':'good metric-money',render:p=>fmt.format(p.profit)},{label:'Рентабельность',render:p=>p.profitability.toFixed(1)+'%'},{label:'',render:p=>projectOpenButton(p.id)}],'Проектов нет.'))}`;
  }else if(type==='profitability'){
    const rows=[...list].sort((a,b)=>b.profitability-a.profitability),rent=totalRent(t),excellent=rows.filter(p=>p.profitability>=50).length,risk=rows.filter(p=>p.profitability<20).length;
    title='Рентабельность';
    body=`${metricHero([metricHeroCard('Рентабельность портфеля',rent.toFixed(1)+'%','Прибыль / Выполнено × 100%','good'),metricHeroCard('Прибыль',fmt.format(t.profit),'прибыль выбранной выборки'),metricHeroCard('≥ 50%',excellent,'проектов с высокой эффективностью','blue'),metricHeroCard('< 20%',risk,'проектов по фактору риска',risk?'bad':'')])}${metricExplain('Как читать показатель','Рентабельность показывает долю прибыли в выполненных работах. Для финансового состояния: ≥ 50% — сильный уровень, 20–49,9% — допустимый, < 20% — фактор риска.')}${metricSection('Рентабельность по проектам','От наиболее рентабельных к наименее рентабельным',metricProjectTable(rows,[{label:'Проект',render:p=>`<b>${esc(p.name)}</b><div class="muted">${esc(p.client||'')}</div>`},{label:'Выполнено',cls:()=> 'blue',render:p=>fmt.format(p.completed)},{label:'Прибыль',cls:p=>p.profit<0?'bad':'good',render:p=>fmt.format(p.profit)},{label:'Рентабельность',cls:p=>p.profitability<20?'bad metric-money':p.profitability>=50?'good metric-money':'blue metric-money',render:p=>p.profitability.toFixed(1)+'%'},{label:'Состояние',render:p=>healthPill(p)},{label:'',render:p=>projectOpenButton(p.id)}],'Проектов нет.'))}`;
  }else if(type==='receivable'){
    const rows=[...list].sort((a,b)=>b.receivable-a.receivable);
    title='Общая дебиторка';sub=`Накопительно на ${dateRu(state.period.end)}`;
    body=`${metricHero([metricHeroCard('Выполнено накопительно',fmt.format(completedCum),'по выбранным проектам','blue'),metricHeroCard('Получено накопительно',fmt.format(receivedCum),'по выбранным проектам','good'),metricHeroCard('Новая дебиторка за период',fmt.format(newDebt),'положительная разница периода','warn'),metricHeroCard('Общая дебиторка проекта',fmt.format(t.receivable),`${debtRatio.toFixed(1)}% от выполненного накопительно`,'warn')])}${metricExplain('Формула общей дебиторки','Для каждого проекта: max(0, Выполнено накопительно − Получено накопительно). Если получено больше выполненного, превышение считается авансом и не создаёт отрицательную дебиторку.')}${metricSection('Дебиторка по проектам','Нажмите сумму для помесячной расшифровки',metricProjectTable(rows,[{label:'Проект',render:p=>`<b>${esc(p.name)}</b><div class="muted">${esc(p.client||'')}</div>`},{label:'Выполнено накоп.',render:p=>fmt.format(p.completed_cumulative)},{label:'Получено накоп.',render:p=>fmt.format(p.received_cumulative)},{label:'Общая дебиторка',cls:()=> 'warn metric-money',render:p=>`<button class="debt-link" data-debt="${p.id}">${fmt.format(p.receivable)}</button>`},{label:'Доля',render:p=>p.debt_ratio.toFixed(1)+'%'},{label:'',render:p=>projectOpenButton(p.id)}],'Проектов нет.'))}`;
  }
  metricDialog(title,sub,`<div class="metric-modal-shell metric-prototype">${body}</div>`)
}
function openHealthDrill(key){const list=filteredProjects().filter(p=>p.financial_health===key);renderHealthDrill(list,key,{filterAction:`Показать только ${healthText(key).toLowerCase()}`})}

async function getProjectDetail(id){if(state.projectCache.has(id))return state.projectCache.get(id);const p=await api(`/api/projects/${id}?${qsPeriod()}`);state.projectCache.set(id,p);return p}
async function openProject(id){state.currentProjectId=id;state.currentEmployeeId=null;state.view='project';state.projectTab='summary';render().catch(showError)}
function within(date){return date>=state.period.start&&date<=state.period.end}
async function renderProject(){const p=await getProjectDetail(state.currentProjectId);$('#crumbCurrent').textContent='/ '+p.name;setContent(`<div class="detail-head"><div class="detail-title"><div class="muted" style="font-size:10px">← <a href="#" id="back" style="color:inherit;text-decoration:none">Вернуться в портфель</a></div><h1>${esc(p.name)}</h1><p>${esc(p.client)} · ${esc(p.description||'')}</p></div><div class="head-actions">${healthPill(p)}<button class="btn" data-add-completion="${p.id}">+ Выполнение</button><button class="btn" data-add-op="${p.id}">+ Операция</button></div></div>${pipelineKpis([p],true)}<div class="tabs"><button class="tab ${state.projectTab==='summary'?'active':''}" data-tab="summary">Сводка</button><button class="tab ${state.projectTab==='operations'?'active':''}" data-tab="operations">Операции</button><button class="tab ${state.projectTab==='team'?'active':''}" data-tab="team">Команда</button><button class="tab ${state.projectTab==='documents'?'active':''}" data-tab="documents">Документы</button></div><div id="projectTab"></div>`);$('#back').onclick=e=>{e.preventDefault();state.view='dashboard';state.currentProjectId=null;render().catch(showError)};$$('[data-tab]').forEach(b=>b.onclick=()=>{state.projectTab=b.dataset.tab;renderProjectTab(p)});bindCommon();renderProjectTab(p)}
function renderProjectTab(p){$$('.tabs [data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.projectTab));const host=$('#projectTab');if(state.projectTab==='summary'){const comps=(p.completions||[]).filter(x=>within(x.completion_date)),ops=(p.transactions||[]).filter(x=>within(x.transaction_date)),expenses=ops.filter(x=>x.type==='expense'),cats={};expenses.forEach(x=>cats[x.category_name]=(cats[x.category_name]||0)+x.amount);host.innerHTML=`<div class="grid2"><div class="panel"><div class="panel-head"><div><h2>Освоение сделки</h2><p>Накопительно на ${dateRu(state.period.end)}</p></div></div><div class="panel-body quick-list"><div class="quick-item clickable" data-metric="completed" data-project-id="${p.id}"><div style="flex:1"><b>Выполнено накопительно</b><small>${fmt.format(p.completed_cumulative)} из ${fmt.format(p.deal_amount)}</small><div class="track"><i class="fill blue" style="width:${progress(p.completed_cumulative,p.deal_amount)}%"></i></div></div><b>${progress(p.completed_cumulative,p.deal_amount).toFixed(1)}%</b></div><div class="quick-item clickable" data-metric="received" data-project-id="${p.id}"><div style="flex:1"><b>Получено накопительно</b><small>${fmt.format(p.received_cumulative)}</small><div class="track"><i class="fill good" style="width:${progress(p.received_cumulative,p.deal_amount)}%"></i></div></div><b>${progress(p.received_cumulative,p.deal_amount).toFixed(1)}%</b></div><div class="quick-item clickable" data-debt="${p.id}"><div><b>Общая дебиторка проекта</b><small>Выполнено накопительно − Получено накопительно</small></div><b class="warn">${fmt.format(p.receivable)}</b></div><div class="quick-item"><div><b>Новая дебиторка за период</b><small>Чистая разница выполнения и поступлений периода</small></div><b class="${p.new_receivable?'warn':'good'}">${fmt.format(p.new_receivable)}</b></div>${p.advance?`<div class="quick-item"><div><b>Аванс клиента</b><small>Получено накопительно больше выполненного</small></div><b class="good">${fmt.format(p.advance)}</b></div>`:''}</div></div><div class="panel"><div class="panel-head"><div><h2>Финансовое состояние: «${healthText(p.financial_health)}»</h2><p>Факт → порог → оценка</p></div></div><div class="panel-body"><div class="factor-grid">${factor('Прибыль',fmt.format(p.profit),p.profit<0?'risk':'excellent','норма ≥ 0 ₽')}${factor('Рентабельность',p.profitability.toFixed(1)+'%',p.profitability<20?'risk':p.profitability>=50?'excellent':'stable','отлично ≥ 50% · риск < 20%')}${factor('Общая дебиторка',`${fmt.format(p.receivable)} · ${p.debt_ratio.toFixed(1)}%`,p.debt_ratio>35?'risk':p.debt_ratio<=25?'excellent':'stable','отлично ≤ 25% · риск > 35%')}</div><div class="threshold-note" style="margin-top:9px">Операционный статус «${statusText(p.status)}» оценивается отдельно.</div></div></div></div><div class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Структура расходов</h2><p>${expenses.length} операций за период</p></div></div><div class="panel-body quick-list">${Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="quick-item"><div style="flex:1"><b>${esc(k)}</b><small>${fmt.format(v)} · ${(v/Math.max(1,p.expenses)*100).toFixed(1)}%</small><div class="track"><i class="fill warn" style="width:${progress(v,Math.max(...Object.values(cats),1))}%"></i></div></div></div>`).join('')||'<div class="muted">Расходов в периоде нет</div>'}</div></div>`;bindMetricLinks(host)}else if(state.projectTab==='operations'){const rows=(p.transactions||[]).filter(x=>within(x.transaction_date)).map(o=>({...o,project_name:p.name}));host.innerHTML=operationTable(rows);$$('[data-open-project]',host).forEach(x=>x.onclick=()=>{})}else if(state.projectTab==='team'){host.innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Команда проекта</h2><p>${p.members.length} участников</p></div><button class="btn primary small" data-add-member="${p.id}">+ Добавить в проект</button></div><div class="panel-body">${p.members.map(m=>`<div class="rank"><div class="avatar">${initials(m.name)}</div><div style="flex:1"><b>${esc(m.name)}</b><div class="muted" style="font-size:9px">${esc(m.role||m.employee_role||'Участник')}</div></div><button class="btn small ghost" data-remove-member="${m.id}">Убрать</button></div>`).join('')||'<div class="muted">Команда не назначена</div>'}</div></div>`;bindCommon();$$('[data-remove-member]',host).forEach(b=>b.onclick=async()=>{if(confirm('Убрать сотрудника из проекта?')){await api(`/api/projects/${p.id}/members/${b.dataset.removeMember}`,{method:'DELETE'});state.projectCache.delete(p.id);await renderProject()}})}else{const docs=(p.documents||[]).filter(x=>within(x.document_date)).map(d=>({...d,project_name:p.name}));host.innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Документы проекта</h2><p>${docs.length} за период</p></div><button class="btn primary small" data-add-document="${p.id}">+ Документ</button></div>${documentTable(docs).replace('<div class="panel">','').replace(/<\/div>$/,'')}</div>`;bindCommon()}}
function factor(label,value,state,threshold){const c=state==='excellent'?'good':state==='risk'?'bad':'blue',t=state==='excellent'?'Отлично':state==='risk'?'Риск':'Стабильно';return `<div class="factor-card ${c}"><div class="factor-title">${label}</div><div class="factor-value">${value}</div><small><b>${t}</b> · ${threshold}</small></div>`}
function bindMetricLinks(root=document){$$('[data-metric]',root).forEach(x=>x.onclick=()=>openMetric(+x.dataset.projectId,x.dataset.metric));$$('[data-debt]',root).forEach(x=>x.onclick=e=>{e.stopPropagation();openDebt(+x.dataset.debt)})}
async function openMetric(id,type){const p=await getProjectDetail(id),comps=(p.completions||[]).filter(x=>within(x.completion_date)),ops=(p.transactions||[]).filter(x=>within(x.transaction_date)),receipts=ops.filter(x=>x.type==='income'),expenses=ops.filter(x=>x.type==='expense');let title='',sub='',body='';if(type==='completed'){title=`Выполнено · ${p.name}`;sub=`${dateRu(state.period.start)} — ${dateRu(state.period.end)}`;body=`${pipelineKpis([p],true)}<div class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Закрытия в периоде</h2></div></div><div class="table-wrap"><table><thead><tr><th>Дата</th><th>Основание</th><th>Комментарий</th><th>Сумма</th></tr></thead><tbody>${comps.map(c=>`<tr><td>${dateRu(c.completion_date)}</td><td>${esc(c.document||'—')}</td><td>${esc(c.comment||'—')}</td><td class="blue">${fmt.format(c.amount)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty-cell">Нет выполнений.</td></tr>'}</tbody></table></div></div>`}else if(type==='received'){title=`Получено · ${p.name}`;sub='Фактические поступления денег';body=`${pipelineKpis([p],true)}<div class="panel" style="margin-top:12px"><div class="table-wrap"><table><thead><tr><th>Дата</th><th>Плательщик / контрагент</th><th>Статья</th><th>Комментарий</th><th>Сумма</th></tr></thead><tbody>${receipts.map(o=>`<tr><td>${dateRu(o.transaction_date)}</td><td>${esc(o.counterparty||'—')}</td><td>${esc(o.category_name)}</td><td>${esc(o.comment||'—')}</td><td class="good">${fmt.format(o.amount)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-cell">Нет поступлений.</td></tr>'}</tbody></table></div></div>`}else if(type==='expenses'){title=`Расходы · ${p.name}`;sub='Все расходные операции периода';body=`${pipelineKpis([p],true)}<div class="panel" style="margin-top:12px"><div class="table-wrap"><table><thead><tr><th>Дата</th><th>Статья</th><th>Сотрудник / контрагент</th><th>Комментарий</th><th>Сумма</th></tr></thead><tbody>${expenses.map(o=>`<tr><td>${dateRu(o.transaction_date)}</td><td>${esc(o.category_name)}</td><td>${esc(o.employee_name||o.counterparty||'—')}</td><td>${esc(o.comment||'—')}</td><td class="bad">${fmt.format(o.amount)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-cell">Нет расходов.</td></tr>'}</tbody></table></div></div>`}else{title=`Прибыль · ${p.name}`;sub='Выполнено − Расходы';body=`<div class="metric-grid">${kpi('Выполнено',fmt.format(p.completed),'выручка периода','blue')}${kpi('Расходы',fmt.format(p.expenses),'затраты периода','expense')}${kpi('Прибыль',fmt.format(p.profit),'Выполнено − Расходы',p.profit<0?'expense':'')}${kpi('Рентабельность',p.profitability.toFixed(1)+'%','Прибыль / Выполнено × 100%')}</div><div class="info-callout"><b>Формула прибыли</b>Полученные деньги не входят в прибыль напрямую. Они отвечают за денежный поток и дебиторку.</div>`}$('#metricTitle').textContent=title;$('#metricSub').textContent=sub;$('#metricBody').innerHTML=body;$('#metricDialog').showModal();bindMetricLinks($('#metricBody'))}
async function openDebt(id){
  const p=await getProjectDetail(id),events=[];
  for(const c of p.completions||[])if(c.completion_date<=state.period.end)events.push({date:c.completion_date,completed:c.amount,received:0});
  for(const o of p.transactions||[])if(o.type==='income'&&o.transaction_date<=state.period.end)events.push({date:o.transaction_date,completed:0,received:o.amount});
  events.sort((a,b)=>a.date.localeCompare(b.date));
  const months={};for(const e of events){const m=e.date.slice(0,7);months[m]??={completed:0,received:0};months[m].completed+=e.completed;months[m].received+=e.received}
  let cc=0,rr=0;const rows=Object.entries(months).map(([m,v])=>{cc+=v.completed;rr+=v.received;return{m,...v,delta:v.completed-v.received,cc,rr,debt:Math.max(0,cc-rr)}});
  $('#debtTitle').textContent=`Общая дебиторка проекта · ${p.name}`;
  $('#debtSub').textContent=`На ${dateRu(state.period.end)}: выполнено накопительно − получено накопительно`;
  $('#debtBody').innerHTML=`<div class="metric-modal-shell debt-prototype">${metricHero([metricHeroCard('Выполнено накопительно',fmt.format(p.completed_cumulative),'все закрытые работы до конца периода','blue'),metricHeroCard('Получено накопительно',fmt.format(p.received_cumulative),'все поступившие деньги до конца периода','good'),metricHeroCard('Новая дебиторка за период',fmt.format(p.new_receivable),`Выполнено ${fmt.format(p.completed)} − Получено ${fmt.format(p.received)}`,'warn'),metricHeroCard('Общая дебиторка проекта',fmt.format(p.receivable),'накопительный остаток на конец периода','warn')])}${metricExplain('Формула общей дебиторки проекта','max(0, Выполнено накопительно − Получено накопительно). В финансовом состоянии используется доля общей дебиторки от накопленного выполнения: ≤ 25% — отлично; 25–35% — стабильно; > 35% — риск.')}${metricSection('Как сформировалась общая дебиторка','Помесячная накопительная расшифровка',metricProjectTable(rows,[{label:'Месяц',render:r=>`<b>${monthRu(r.m)}</b>`},{label:'Выполнено',cls:()=> 'blue',render:r=>fmt.format(r.completed)},{label:'Получено',cls:()=> 'good',render:r=>fmt.format(r.received)},{label:'Разница месяца',cls:r=>r.delta>0?'warn':r.delta<0?'good':'',render:r=>`${r.delta>0?'+':''}${fmt.format(r.delta)}`},{label:'Выполнено накоп.',render:r=>fmt.format(r.cc)},{label:'Получено накоп.',render:r=>fmt.format(r.rr)},{label:'Общая дебиторка',cls:()=> 'warn metric-money',render:r=>fmt.format(r.debt)}],'Нет истории по проекту.'))}</div>`;
  $('#debtDialog').showModal();$('#debtDialog').scrollTop=0
}
function roleOptions(){return [...new Set(state.employees.map(e=>String(e.role||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ru'))}
function syncProjectManagers(){const f=$('#projectForm'),role=f.manager_role.value;f.manager_employee_id.disabled=!role;const people=role?state.employees.filter(e=>String(e.role||'').trim()===role):[];f.manager_employee_id.innerHTML=role?'<option value="">Выберите менеджера</option>'+people.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join(''):'<option value="">Сначала выберите роль</option>';updateFormState(f)}
function openProjectDialog(){const f=$('#projectForm');f.reset();f.deal_date.value=localISO();const roles=roleOptions();f.manager_role.innerHTML='<option value="">Выберите роль</option>'+roles.map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('');f.manager_employee_id.innerHTML='<option value="">Сначала выберите роль</option>';f.manager_employee_id.disabled=true;if(!roles.length)toast('Сначала заполните роль хотя бы у одного сотрудника');$('#projectDialog').showModal();updateFormState(f)}
function openOperationDialog(id=null){if(!state.projects.length)return toast('Сначала создайте проект');const f=$('#operationForm');f.reset();f.transaction_date.value=localISO();f.project_id.innerHTML=state.projects.map(p=>`<option value="${p.id}" ${p.id===+id?'selected':''}>${esc(p.name)}</option>`).join('');syncOpForm();$('#operationDialog').showModal();updateFormState(f)}
function syncOpForm(){const f=$('#operationForm'),type=f.type.value,prevCategory=f.category_id.value,available=state.categories.filter(c=>c.type===type);f.category_id.innerHTML=available.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');if(available.some(c=>String(c.id)===String(prevCategory)))f.category_id.value=prevCategory;const income=type==='income',expense=type==='expense',category=state.categories.find(c=>String(c.id)===String(f.category_id.value)),employeeMode=expense&&category?.party_mode==='employee',requiredRole=employeeMode?String(category.employee_role||'').trim():'',roleKey=requiredRole.toLocaleLowerCase('ru-RU'),employees=employeeMode?state.employees.filter(e=>String(e.role||'').trim().toLocaleLowerCase('ru-RU')===roleKey):state.employees;$('#employeeField').dataset.hidden=employeeMode?'false':'true';$('#counterpartyField').dataset.hidden='false';f.employee_id.required=employeeMode;f.employee_id.disabled=!employeeMode;f.counterparty.disabled=false;f.counterparty.required=income||(expense&&!employeeMode);f.employee_id.innerHTML=`<option value="">${requiredRole?`Выберите: ${esc(requiredRole)}`:'Выберите сотрудника'}</option>`+employees.map(e=>`<option value="${e.id}">${esc(e.name)}${e.role?` · ${esc(e.role)}`:''}</option>`).join('');const employeeLabel=$('#employeeField label'),employeeHelp=$('#employeeField .form-help'),label=$('#counterpartyLabel'),help=$('#counterpartyHelp');if(employeeLabel)employeeLabel.textContent=employeeMode?`Сотрудник · ${requiredRole||'роль не настроена'} *`:'Сотрудник';if(employeeHelp)employeeHelp.textContent=employeeMode?`Показываются только сотрудники роли «${requiredRole||'не настроена'}».`:'Для внутренних затрат можно привязать конкретного сотрудника.';if(label)label.textContent=income?'Плательщик / контрагент *':employeeMode?'Контрагент (необязательно)':'Контрагент *';if(help)help.textContent=income?'Укажите конкретного плательщика. Один проект может иметь несколько плательщиков — каждый платёж сохраняется отдельно.':employeeMode?'При необходимости можно дополнительно указать контрагента.':'Укажите конкретного внешнего контрагента / поставщика.';if(!employeeMode)f.employee_id.value='';updateFormState(f)}
function openCompletionDialog(id=null){if(!state.projects.length)return toast('Сначала создайте проект');const f=$('#completionForm');f.reset();f.completion_date.value=localISO();f.project_id.innerHTML=state.projects.map(p=>`<option value="${p.id}" ${p.id===+id?'selected':''}>${esc(p.name)}</option>`).join('');$('#completionDialog').showModal();updateFormState(f)}
function openDocumentDialog(id=null){if(!state.projects.length)return toast('Сначала создайте проект');const f=$('#documentForm');f.reset();f.document_date.value=localISO();f.project_id.innerHTML=state.projects.map(p=>`<option value="${p.id}" ${p.id===+id?'selected':''}>${esc(p.name)}</option>`).join('');$('#documentDialog').showModal();updateFormState(f)}
function openMemberDialog(id){const f=$('#memberForm');f.reset();f.project_id.value=id;f.employee_id.innerHTML='<option value="">Выберите сотрудника</option>'+state.employees.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.role||'')}</option>`).join('');$('#memberDialog').showModal();updateFormState(f)}
function openEmployeeEditDialog(id){const e=state.employees.find(x=>x.id===id);if(!e)return toast('Сотрудник не найден');const f=$('#employeeEditForm');f.reset();f.id.value=e.id;f.name.value=e.name||'';f.email.value=e.email||'';f.role.value=e.role||'';f.bitrix_user_id.value=e.bitrix_user_id||'';$('#employeeEditDialog').showModal();updateFormState(f)}
function syncCategoryForm(){const f=$('#newCategoryForm'),expense=f.type.value==='expense',employeeMode=expense&&f.party_mode.value==='employee',roleField=$('#categoryEmployeeRoleField'),bindingFields=$('#categoryBindingFields'),prev=f.employee_role.value,roles=[...new Set(state.employees.map(e=>String(e.role||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ru'));bindingFields.dataset.hidden=expense?'false':'true';f.party_mode.disabled=!expense;if(!expense)f.party_mode.value='counterparty';roleField.dataset.hidden=employeeMode?'false':'true';f.employee_role.disabled=!employeeMode;f.employee_role.required=employeeMode;f.employee_role.innerHTML='<option value="">Выберите роль</option>'+roles.map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('');if(employeeMode&&roles.includes(prev))f.employee_role.value=prev;updateFormState(f)}
function bindCommon(){$$('[data-add-project]').forEach(b=>b.onclick=openProjectDialog);$$('[data-add-op]').forEach(b=>b.onclick=()=>openOperationDialog(b.dataset.addOp||state.currentProjectId));$$('[data-add-completion]').forEach(b=>b.onclick=()=>openCompletionDialog(b.dataset.addCompletion||state.currentProjectId));$$('[data-add-document]').forEach(b=>b.onclick=()=>openDocumentDialog(b.dataset.addDocument||state.currentProjectId));$$('[data-add-employee]').forEach(b=>b.onclick=()=>{const f=$('#employeeForm');f.reset();$('#employeeDialog').showModal();updateFormState(f)});$$('[data-new-category]').forEach(b=>b.onclick=()=>{const f=$('#newCategoryForm');f.reset();syncCategoryForm();$('#newCategoryDialog').showModal();updateFormState(f)});$$('[data-add-member]').forEach(b=>b.onclick=()=>openMemberDialog(+b.dataset.addMember));$$('[data-open-project]').forEach(x=>x.onclick=()=>openProject(+x.dataset.openProject));bindMetricLinks()}
async function render(){updateTop();try{if(state.view==='dashboard')return renderDashboard();if(state.view==='operations')return renderOperations();if(state.view==='documents')return renderDocuments();if(state.view==='categories')return renderCategories();if(state.view==='employees')return renderEmployees();if(state.view==='employeeDetail')return renderEmployeeDetail();if(state.view==='project')return renderProject()}catch(e){setContent(`<div class="error-box"><b>Не удалось загрузить данные</b><br>${esc(e.message)}</div>`);throw e}}
function formSubmitButton(form){return form.querySelector('.form-actions button[type="submit"]')}
function requiredControlReady(control){if(!control.required||control.disabled)return true;if(control.type==='checkbox'||control.type==='radio')return control.checked;const value=String(control.value??'').trim();if(!value)return false;if(control.type==='number'&&!Number.isFinite(Number(value)))return false;return control.validity.valid}
function isFormReady(form){if(!form)return false;return [...form.elements].every(requiredControlReady)&&form.checkValidity()}
function updateFormState(form){if(!form)return;const btn=formSubmitButton(form);if(!btn)return;const ready=isFormReady(form);btn.disabled=!ready;btn.setAttribute('aria-disabled',String(!ready));btn.dataset.ready=ready?'true':'false'}
function armFormValidation(form){if(!form)return;for(const ev of ['input','change'])form.addEventListener(ev,()=>updateFormState(form));updateFormState(form)}

const liveFilterTimers=new Map();
function bindLiveFilter(input,onValue,renderer,delay=140){
  if(!input)return;
  input.addEventListener('input',()=>{
    const id=input.id;
    const start=typeof input.selectionStart==='number'?input.selectionStart:null;
    const end=typeof input.selectionEnd==='number'?input.selectionEnd:null;
    onValue(input.value);
    clearTimeout(liveFilterTimers.get(id));
    liveFilterTimers.set(id,setTimeout(async()=>{
      try{
        await renderer();
        const next=$('#'+id);
        if(!next)return;
        next.focus({preventScroll:true});
        if(start!==null&&typeof next.setSelectionRange==='function'){
          const safeStart=Math.min(start,next.value.length),safeEnd=Math.min(end??start,next.value.length);
          next.setSelectionRange(safeStart,safeEnd);
        }
      }catch(err){showError(err)}
      finally{liveFilterTimers.delete(id)}
    },delay));
  });
}

function bindNumericFilter(input,onValue,renderer){
  if(!input)return;
  input.addEventListener('input',()=>onValue(input.value));
  input.addEventListener('change',()=>renderer().catch(showError));
  input.addEventListener('keydown',e=>{
    if(e.key==='Enter'){
      e.preventDefault();
      onValue(input.value);
      input.blur();
    }
  });
}

function armAllForms(){['projectForm','operationForm','completionForm','documentForm','employeeForm','employeeEditForm','memberForm','newCategoryForm'].forEach(id=>armFormValidation($('#'+id)))}
function setupForms(){$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());armAllForms();$('#operationForm').type.onchange=syncOpForm;$('#operationForm').category_id.onchange=syncOpForm;$('#newCategoryForm').type.onchange=syncCategoryForm;$('#newCategoryForm').party_mode.onchange=syncCategoryForm;$('#projectForm').manager_role.onchange=syncProjectManagers;$('#projectForm').onsubmit=async e=>{e.preventDefault();if(!isFormReady(e.currentTarget))return updateFormState(e.currentTarget);const d=Object.fromEntries(new FormData(e.currentTarget));await api('/api/projects',{method:'POST',body:JSON.stringify({...d,manager_employee_id:d.manager_employee_id||null})});$('#projectDialog').close();toast('Проект создан');await refresh()};$('#operationForm').onsubmit=async e=>{e.preventDefault();if(!isFormReady(e.currentTarget))return updateFormState(e.currentTarget);const d=Object.fromEntries(new FormData(e.currentTarget));await api('/api/transactions',{method:'POST',body:JSON.stringify({...d,employee_id:d.employee_id||null})});$('#operationDialog').close();toast('Операция добавлена');await refresh()};$('#completionForm').onsubmit=async e=>{e.preventDefault();if(!isFormReady(e.currentTarget))return updateFormState(e.currentTarget);const d=Object.fromEntries(new FormData(e.currentTarget));await api('/api/completions',{method:'POST',body:JSON.stringify(d)});$('#completionDialog').close();toast('Выполнение зафиксировано');await refresh()};$('#documentForm').onsubmit=async e=>{e.preventDefault();if(!isFormReady(e.currentTarget))return updateFormState(e.currentTarget);const d=Object.fromEntries(new FormData(e.currentTarget));await api('/api/documents',{method:'POST',body:JSON.stringify(d)});$('#documentDialog').close();toast('Документ добавлен');await refresh()};$('#employeeForm').onsubmit=async e=>{e.preventDefault();if(!isFormReady(e.currentTarget))return updateFormState(e.currentTarget);const d=Object.fromEntries(new FormData(e.currentTarget));await api('/api/employees',{method:'POST',body:JSON.stringify(d)});$('#employeeDialog').close();toast('Сотрудник создан');await refresh()};$('#employeeEditForm').onsubmit=async e=>{e.preventDefault();if(!isFormReady(e.currentTarget))return updateFormState(e.currentTarget);const d=Object.fromEntries(new FormData(e.currentTarget)),id=d.id;delete d.id;await api(`/api/employees/${id}`,{method:'PATCH',body:JSON.stringify(d)});$('#employeeEditDialog').close();toast('Данные сотрудника обновлены');await refresh()};$('#newCategoryForm').onsubmit=async e=>{e.preventDefault();if(!isFormReady(e.currentTarget))return updateFormState(e.currentTarget);const d=Object.fromEntries(new FormData(e.currentTarget));await api('/api/categories',{method:'POST',body:JSON.stringify(d)});$('#newCategoryDialog').close();toast('Статья создана');await refresh()};$('#memberForm').onsubmit=async e=>{e.preventDefault();if(!isFormReady(e.currentTarget))return updateFormState(e.currentTarget);const d=Object.fromEntries(new FormData(e.currentTarget));await api(`/api/projects/${d.project_id}/members`,{method:'POST',body:JSON.stringify({employee_id:d.employee_id,role:d.role})});$('#memberDialog').close();state.projectCache.delete(+d.project_id);toast('Сотрудник добавлен в проект');await renderProject()}}
function setupNav(){$$('.nav button').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;state.currentProjectId=null;state.currentEmployeeId=null;state.selectedProjectId=null;refresh().catch(showError)});$('#lightBtn').onclick=()=>setTheme('light');$('#darkBtn').onclick=()=>setTheme('dark')}
function setTheme(v){document.documentElement.dataset.theme=v;localStorage.setItem('pf_theme',v);$('#lightBtn').classList.toggle('active',v==='light');$('#darkBtn').classList.toggle('active',v==='dark')}
function initTheme(){setTheme(localStorage.getItem('pf_theme')||'light')}
function initBitrix(){try{if(window.BX24?.init){window.BX24.init(()=>{window.BX24.callMethod('user.current',{},r=>{const u=r.data?.();if(u){state.bitrixUser=u;$('#integrationState').textContent=`Битрикс24 · ${u.NAME||''} ${u.LAST_NAME||''}`.trim();$('#userBadge').textContent=initials(`${u.NAME||''} ${u.LAST_NAME||''}`)}})})}}catch(e){console.warn('Bitrix24 SDK unavailable',e)}}
async function boot(){initTheme();setupNav();setupForms();initBitrix();await loadBase();await render()}
boot().catch(showError);
